window.__PRODUCTIVITY_INTERNALS = { TOOLS: [
  {"id":"eisenhower","n":"Eisenhower Matrix","f":"prioritise","m":"both","t":30,"rec":true,"fm":"structured","out":["me","manager"],"d":["matrix",{"x":"Urgent →","y":"Important ↑","q":["Schedule","Do now","Drop","Delegate"]}],"why":"Sorts a messy list into four actions, so the urgent does not crowd out the important.","solo":["List every task on the table. Keep it to about fifteen items.","Ask two questions of each: is it important? is it urgent?","Put each task in one box. Do the top right now, schedule the top left, drop the bottom left.","Delegate the bottom right, or send a one-line reply that hands it back."],"team":["Each person runs the matrix on their own list first, for five minutes.","Compare the lists and move shared items into the same box.","Agree who owns each Delegate item before the meeting ends."],"ex":"Restore checkout first. Put budget work in the calendar so the incident does not erase it.","src":"Quote attributed to Dwight D. Eisenhower (1954 speech). Popularised by Stephen Covey, The 7 Habits of Highly Effective People (1989).","sample":["Schedule budget work for Thursday","Restore broken checkout","Remove duplicate report","Ask Lina to own the follow-up"],"fr":{"n":"Matrice d’Eisenhower","why":"Classe les tâches selon leur urgence et leur importance.","solo":["Liste tes tâches","Évalue leur urgence et leur importance","Traite les urgences importantes et réserve un créneau pour le reste"],"team":["Classez les tâches ensemble","Attribuez les urgences","Vérifiez les délégations vendredi"],"d":["matrix",{"x":"Urgence →","y":"Importance ↑","q":["Planifier","Faire maintenant","Éliminer","Déléguer"]}],"src":"Discours de Dwight D. Eisenhower (1954), puis popularisation par Stephen Covey (1989).","sample":["Préparer le budget jeudi","Rétablir le paiement en panne","Supprimer le rapport doublon","Confier le suivi à Lina"],"ex":"Rétablis d’abord le paiement. Réserve un créneau au budget pour que l’incident ne le fasse pas disparaître.","exampleNote":"Rétablis d’abord le paiement. Réserve un créneau au budget pour que l’incident ne le fasse pas disparaître.","case":{"scene":"Une boutique doit gérer une panne de paiement, une échéance budgétaire et des rapports en attente.","check":"Vérifie que le paiement fonctionne et que le créneau du budget est toujours réservé jeudi."}},"exampleNote":"Restore checkout first. Put budget work in the calendar so the incident does not erase it.","case":{"scene":"A small shop has a checkout outage, a budget deadline and a backlog of reporting tasks.","check":"Check that checkout works and that the budget slot is still booked on Thursday."}},
  {"id":"pareto","n":"Pareto 80/20","f":"prioritise","m":"solo","t":30,"rec":true,"fm":"structured","out":["me","manager"],"d":["bars",[["Late feedback",0,0.52],["Slow approvals",0,0.25],["Dependencies",0,0.13],["Rework",0,0.1]]],"why":"Shows which few causes produce most of the problem, so the effort goes where it counts.","solo":["For two weeks, log the cause of each delay, error or complaint.","Count each cause and sort from largest to smallest.","Work on the top one or two causes. Count again after a month."],"team":["Pool the causes from everyone's log.","Vote on the top three causes and agree who fixes each one."],"ex":"Pilot a 24-hour feedback deadline on one project. Tackle approvals next if they still account for a large share of incidents.","src":"Vilfredo Pareto (1896, income distribution). The 80/20 name was given by Joseph Juran (1940s to 1950s).","sample":["52 incidents","25 incidents","13 incidents","10 incidents"],"fr":{"n":"Principe de Pareto","why":"Repère les causes qui contribuent le plus au problème mesuré.","solo":["Compte les incidents sur une période","Classe les causes par fréquence","Traite la première puis mesure de nouveau"],"team":["Mettez-vous d’accord sur l’unité","Vérifiez les catégories","Nommez un responsable de la cause dominante"],"d":["bars",[["Retours tardifs",0,0.52],["Validations lentes",0,0.25],["Dépendances",0,0.13],["Reprises",0,0.1]]],"src":"Vilfredo Pareto, travaux sur la répartition des revenus (1896). Joseph Juran a popularisé la règle des 80/20 au milieu du XXe siècle.","sample":["52 incidents","25 incidents","13 incidents","10 incidents"],"ex":"Teste un délai de retour de 24 h sur un projet. Traite ensuite les validations si elles représentent toujours une part importante des incidents.","exampleNote":"Teste un délai de retour de 24 h sur un projet. Traite ensuite les validations si elles représentent toujours une part importante des incidents.","case":{"scene":"Une équipe de livraison recense 100 incidents en avril. Elle dispose d’une semaine pour agir et classe chaque incident par cause principale.","check":"Teste un délai de retour de 24 h sur un projet. Compare le nombre d’incidents liés aux retours tardifs pour 100 livraisons sur une période comparable.","headlines":["100 incidents et une semaine pour agir","Deux causes concentrent 77 % des incidents","Tester un délai de retour de 24 h","Mesurer le taux d’incidents au prochain cycle"]}},"exampleNote":"Pilot a 24-hour feedback deadline on one project. Tackle approvals next if they still account for a large share of incidents.","case":{"scene":"A delivery team logs 100 incidents in April. It has one week to address recurring delays and classifies each incident by its primary cause.","check":"Test a 24-hour feedback deadline on one project. Compare the number of late-feedback incidents per 100 deliveries in the next comparable period.","headlines":["100 incidents and one week to act","Two causes account for 77% of incidents","Pilot a 24-hour feedback deadline","Measure the incident rate next cycle"]}},
  {"id":"eat-the-frog","n":"Eat the Frog","f":"prioritise","m":"solo","t":15,"rec":true,"fm":"casual","out":["me"],"d":["flow",["Pick the task you most avoid","Do it first","Then the rest of the list"]],"why":"Starts the day with the task you would most like to put off, while your attention is still fresh.","solo":["Each evening, choose the task you are most likely to avoid tomorrow.","Do it first thing, before email.","Then work through the rest of the list."],"team":["Each person names their 'frog' in the team channel at the start of the day.","At the end of the day, share the blocker, not only the result."],"ex":"Before opening email, finish one visible piece of the report: the introduction.","src":"Brian Tracy, Eat That Frog! (2001). The phrase is also attributed to Mark Twain; that attribution is not verified.","sample":["Draft the report introduction","9:00–9:40","Check email afterwards"],"fr":{"n":"Commencer par le plus difficile","why":"Réserve ton premier créneau à la tâche que tu repousses.","solo":["Choisis une tâche importante que tu évites","Définis un premier résultat visible","Travaille dessus avant d’ouvrir ta messagerie"],"team":["Identifiez un blocage prioritaire","Libérez un créneau commun","Vérifiez le résultat en fin de matinée"],"d":["flow",["Tâche évitée","Premier créneau","Autres tâches"]],"src":"Brian Tracy, Eat That Frog! (2001). L’attribution de la formule à Mark Twain reste incertaine.","sample":["Rédiger l’introduction du rapport","9 h à 9 h 40","Traiter les courriels ensuite"],"ex":"Avant d’ouvrir la messagerie, termine une partie visible du rapport : l’introduction.","exampleNote":"Avant d’ouvrir la messagerie, termine une partie visible du rapport : l’introduction.","case":{"scene":"Un rapport est attendu demain. Son introduction a déjà été repoussée deux fois au profit de courriels faciles à traiter.","check":"Ouvre le brouillon à 9 h et termine une introduction qu’un collègue pourra relire à 9 h 40."}},"exampleNote":"Before opening email, finish one visible piece of the report: the introduction.","case":{"scene":"A report is due tomorrow. The introduction has slipped twice while the author answers easy emails.","check":"Open the draft at 9 am and finish an introduction a colleague could review at 9:40."}},
  {"id":"abcde","n":"ABCDE Method","f":"prioritise","m":"both","t":30,"rec":true,"fm":"structured","out":["me","manager"],"d":["columns",["A · Must","B · Should","C · Nice","D · Delegate","E · Eliminate"]],"why":"Rank tasks by the consequences of not doing them: A is essential, E can be eliminated.","solo":["Write every task before ranking.","Give each task A, B, C, D or E based on its consequences.","Finish A tasks before touching B tasks."],"team":["Ask each participant to complete the abcde canvas individually.","Compare patterns without forcing early agreement.","Finish with one owner, one action and a date."],"ex":"The application has a deadline. Cosmetic changes can wait, and a duplicate task can go.","src":"Brian Tracy, Eat That Frog! (2001).","sample":["Submit the application","Review attachments","Redo colours","Book the room","Cancel the duplicate"],"fr":{"n":"Méthode ABCDE","why":"Classe les tâches selon les conséquences de les laisser de côté.","solo":["Écris ta liste","Attribue une lettre à chaque tâche","Termine les A avant les B"],"team":["Comparez les conséquences","Décidez qui prend les D","Retirez les E de la liste commune"],"d":["columns",["A · Impératif","B · Souhaitable","C · Facultatif","D · Déléguer","E · Éliminer"]],"src":"Brian Tracy, Eat That Frog! (2001).","sample":["Rendre le dossier","Relire les annexes","Refaire les couleurs","Réserver la salle","Annuler le doublon"],"ex":"Le dossier a une échéance. Les retouches visuelles peuvent attendre et le doublon peut être supprimé.","exampleNote":"Le dossier a une échéance. Les retouches visuelles peuvent attendre et le doublon peut être supprimé.","case":{"scene":"Un appel à projets clôture aujourd’hui. L’équipe a une matinée pour les retouches, les annexes et la réservation de salle.","check":"Vérifie que le dossier est envoyé avant de passer du temps sur la mise en forme."}},"exampleNote":"The application has a deadline. Cosmetic changes can wait, and a duplicate task can go.","case":{"scene":"A grant application closes today. The team has a morning for edits, attachments and room logistics.","check":"Check that the application was sent before spending time on formatting."}},
  {"id":"ivy-lee","n":"Ivy Lee Method","f":"prioritise","m":"solo","t":10,"rec":true,"fm":"casual","out":["me"],"d":["flow",["Write six tasks for tomorrow","Rank them 1 to 6","Work on task 1 until it is done","Then task 2, and so on","Move unfinished tasks to tomorrow","Review the list each evening"]],"why":"Ends the day with six ranked tasks, so the next morning starts without a choice to make.","solo":["Each evening, write the six most important tasks for tomorrow.","Rank them from 1 to 6.","Next morning, work on task 1 until it is done before opening task 2.","Move anything unfinished to tomorrow's list."],"team":["Each person shares their ranked top three at the start of the day.","Note who is blocked on whom, and fix it before lunch."],"ex":"Checkout stays first until it passes. Move unfinished icon work to tomorrow’s ranked list.","src":"Ivy Lee and Charles Schwab, a 1918 anecdote repeated in many books. The details are not verified.","sample":["Six launch tasks","Checkout first","Test checkout","Test the receipt","Move icons to tomorrow","Review at 5 pm"],"fr":{"n":"Méthode Ivy Lee","why":"Prépare une liste courte et ordonnée pour commencer sans hésiter.","solo":["Écris six tâches pour demain","Classe-les par importance","Termine chacune avant de passer à la suivante"],"team":["Préparez six priorités","Confirmez leur ordre","Revoyez les reports le lendemain"],"d":["flow",["Six tâches","Classement","Première tâche","Suite","Report","Bilan du soir"]],"src":"Anecdote de 1918 associant Ivy Lee et Charles Schwab. Les détails restent incertains.","sample":["Six tâches de lancement","Paiement en tête","Tester le paiement","Tester le reçu","Reporter les icônes","Revoir à 17 h"],"ex":"Le paiement reste en tête jusqu’à validation. Les icônes inachevées passent dans la liste ordonnée de demain.","exampleNote":"Le paiement reste en tête jusqu’à validation. Les icônes inachevées passent dans la liste ordonnée de demain.","case":{"scene":"Six tâches de lancement se disputent l’attention d’un développeur. Le paiement est la première dépendance de la mise en ligne.","check":"À 17 h, note les tests réussis et reporte les tâches restantes dans l’ordre."}},"exampleNote":"Checkout stays first until it passes. Move unfinished icon work to tomorrow’s ranked list.","case":{"scene":"Six launch tasks compete for a developer’s attention. Checkout is the first dependency for the release.","check":"At 5 pm, record what passed and move unfinished items to tomorrow in order."}},
  {"id":"rule135","n":"1-3-5 Rule","f":"prioritise","m":"both","t":10,"rec":true,"fm":"structured","out":["me","manager"],"d":["columns",["1 big task","3 medium tasks","5 small tasks"]],"why":"Make a realistic daily list: one big task, three medium tasks and five small tasks.","solo":["Choose the single outcome that would make the day worthwhile.","Add three important tasks that take less effort.","Add five small tasks, then stop adding."],"team":["Ask each participant to complete the rule135 canvas individually.","Compare patterns without forcing early agreement.","Finish with one owner, one action and a date."],"ex":"Protect time for the proposal. Fit the smaller work around that commitment.","src":"Popularised by The Muse; no sole verified inventor.","sample":["Finish the proposal","Review, price and schedule","Five short messages"],"fr":{"n":"Règle 1–3–5","why":"Limite la journée à une grande tâche, trois moyennes et cinq petites.","solo":["Choisis le résultat majeur","Ajoute trois tâches moyennes","Complète avec cinq petites si la capacité le permet"],"team":["Estimez la charge de chacun","Répartissez les tâches majeures","Gardez une marge pour les imprévus"],"d":["columns",["Une grande","Trois moyennes","Cinq petites"]],"src":"Méthode popularisée par The Muse. Inventeur unique non établi.","sample":["Finir la proposition","Relire, chiffrer, planifier","Cinq messages courts"],"ex":"Protège le créneau de la proposition. Répartis les petites tâches autour.","exampleNote":"Protège le créneau de la proposition. Répartis les petites tâches autour.","case":{"scene":"Un indépendant a une journée avant la revue d’une proposition et neuf tâches en concurrence.","check":"En fin de journée, vérifie que la proposition est prête à relire avant de compter les petites tâches."}},"exampleNote":"Protect time for the proposal. Fit the smaller work around that commitment.","case":{"scene":"A freelancer has one workday before a proposal review and nine competing tasks.","check":"At close, verify that the proposal is ready to review before counting the smaller tasks."}},
  {"id":"moscow","n":"MoSCoW","f":"prioritise","m":"both","t":60,"rec":false,"fm":"formal","out":["manager","clients"],"d":["columns",["Must have","Should have","Could have","Won’t have this time"]],"why":"Settles scope fast by sorting each item into one of four buckets, and says out loud what will not be done.","solo":["List every item the goal needs.","Label each one: Must (the goal fails without it), Should, Could, or Won’t this round.","If the Musts alone take more time than you have, split the goal into two."],"team":["Write items on sticky notes. Each stakeholder places their own label.","Debate only the items where labels disagree.","Read the Won’t list aloud, so nobody thinks something was forgotten."],"ex":"The launch depends on sign-in. Record social sign-in as outside this release.","src":"Dai Clegg, for the DSDM agile method (1994).","sample":["Sign-in","Password reset","Dark mode","Social sign-in"],"fr":{"n":"Méthode MoSCoW","why":"Fixe le périmètre en séparant les exigences indispensables des options.","solo":["Liste les exigences","Teste ce qui rendrait la livraison inutilisable","Reporte les options au-delà de la capacité"],"team":["Validez les indispensables","Arbitrez les désaccords avec le décideur","Documentez les exclusions"],"d":["columns",["Indispensable","Souhaitable","Possible","Hors périmètre"]],"src":"Dai Clegg, méthode agile DSDM (1994).","sample":["Connexion","Réinitialisation du mot de passe","Thème sombre","Connexion sociale"],"ex":"Le lancement dépend de la connexion. Note que la connexion sociale sort du périmètre de cette version.","exampleNote":"Le lancement dépend de la connexion. Note que la connexion sociale sort du périmètre de cette version.","case":{"scene":"Une équipe produit peut livrer une connexion de base ce cycle. Les options de connexion supplémentaires mobilisent le même temps de développement.","check":"Demande si le produit reste utilisable sans chaque fonction. Consigne le périmètre convenu."}},"exampleNote":"The launch depends on sign-in. Record social sign-in as outside this release.","case":{"scene":"A product team can ship a basic login this sprint. Extra sign-in options compete for the same engineering time.","check":"Ask whether the product can be used without each proposed feature. Record the agreed release boundary."}},
  {"id":"impact-effort","n":"Impact–Effort Matrix","f":"prioritise","m":"both","t":20,"rec":true,"fm":"casual","out":["me","manager"],"d":["matrix",{"x":"Effort →","y":"Impact ↑","q":["Quick wins","Major projects","Fill-ins","Thankless tasks"]}],"why":"Puts ideas on two axes, so quick wins are visible at a glance and heavy work is weighed against its payoff.","solo":["Write each task on its own card.","Place each card by Impact (up is high) and Effort (right is high).","Do the quick wins now. Schedule the major projects. Drop the thankless tasks."],"team":["Place the cards on a shared wall together. Disagreements become questions.","Name the quick wins and give each one an owner."],"ex":"Repair the broken link now. Estimate the checkout redesign separately because it takes more work.","src":"No verified single author. A common two-by-two in product and consulting work.","sample":["Fix the broken link","Redesign checkout","Rename a folder","Redraw every icon"],"fr":{"n":"Matrice impact–effort","why":"Compare la valeur attendue et le travail nécessaire avant de choisir.","solo":["Définis une mesure d’impact","Estime l’effort sur la même échelle","Choisis un gain rapide et examine les grands projets"],"team":["Estimez séparément","Discutez les écarts","Retenez deux actions pour le cycle"],"d":["matrix",{"x":"Effort →","y":"Impact ↑","q":["Gains rapides","Grands projets","Tâches d’appoint","À écarter"]}],"src":"Matrice courante en gestion de produit et en conseil. Auteur unique non établi.","sample":["Corriger le lien cassé","Refondre le paiement","Renommer un dossier","Recréer toutes les icônes"],"ex":"Répare le lien cassé maintenant. Chiffre la refonte du paiement séparément, car elle demande plus de travail.","exampleNote":"Répare le lien cassé maintenant. Chiffre la refonte du paiement séparément, car elle demande plus de travail.","case":{"scene":"Une boutique peut faire une petite correction cette semaine. Un lien cassé bloque certains acheteurs et la refonte du paiement prendrait plusieurs semaines.","check":"Vérifie que le lien fonctionne et mesure combien d’acheteurs abandonnent encore à cette étape."}},"exampleNote":"Repair the broken link now. Estimate the checkout redesign separately because it takes more work.","case":{"scene":"A shop can do one small fix this week. A broken link blocks some buyers and a checkout redesign needs several weeks.","check":"Confirm the repaired link works and measure how often buyers still abandon that step."}},
  {"id":"rice","n":"RICE Scoring","f":"prioritise","m":"team","t":60,"rec":true,"fm":"structured","out":["manager","clients"],"d":["grid",{"cols":["Reach","Impact","Confidence","Effort"],"rows":["Feature A","Feature B"]}],"why":"Adds reach and effort to ICE, so a popular but expensive feature does not win by default.","solo":["Estimate Reach: how many people it touches in a set period.","Score Impact, Confidence (as a percentage) and Effort in person-weeks.","Calculate Reach × Impact × Confidence ÷ Effort. Sort the list by the result."],"team":["Agree the time period and the Impact scale before anyone scores.","Each owner estimates the Effort of their own part.","Review the top five together and write down the assumptions."],"ex":"Both features use the same time window. Feature A scores 160 and Feature B scores 80.","src":"Sean McBride, Intercom blog (2016).","sample":["400 × 2 × 80% ÷ 4 = 160","800 × 1 × 50% ÷ 5 = 80"],"fr":{"n":"Score RICE","why":"Classe les options à partir de leur portée, de leur impact, de la confiance et de l’effort.","solo":["Fixe une période et estime la portée","Multiplie portée, impact et confiance","Divise par l’effort puis vérifie les hypothèses"],"team":["Alignez les échelles","Relevez les estimations fragiles","Comparez les scores avant de trancher"],"d":["grid",{"cols":["Portée","Impact","Confiance","Effort"],"rows":["Fonction A","Fonction B"]}],"src":"Sean McBride, blog d’Intercom (2016).","sample":["400 × 2 × 80 % ÷ 4 = 160","800 × 1 × 50 % ÷ 5 = 80"],"ex":"Les deux fonctions sont évaluées sur la même période. La fonction A obtient 160 points, contre 80 pour la fonction B.","sampleCells":{"c0-0":"400","c0-1":"2","c0-2":"80 %","c0-3":"4","c1-0":"800","c1-1":"1","c1-2":"50 %","c1-3":"5"},"exampleNote":"Les deux fonctions sont évaluées sur la même période. La fonction A obtient 160 points, contre 80 pour la fonction B.","case":{"scene":"Une équipe ne peut livrer qu’une fonction ce trimestre. Elle estime la portée sur le même trimestre et l’effort en personnes-mois.","check":"Vérifie les hypothèses de portée et de confiance avant d’engager l’option à 160 points."}},"sampleCells":{"c0-0":"400","c0-1":"2","c0-2":"80%","c0-3":"4","c1-0":"800","c1-1":"1","c1-2":"50%","c1-3":"5"},"exampleNote":"Both features use the same time window. Feature A scores 160 and Feature B scores 80.","case":{"scene":"A team has room for one feature this quarter. It estimates reach over the same quarter and effort in person-months.","check":"Recheck the reach and confidence assumptions before committing to the 160-point option."}},
  {"id":"kano-grid","n":"Kano Model","f":"prioritise","m":"team","t":60,"rec":false,"fm":"formal","out":["manager","clients"],"d":["grid",{"cols":["Feature","If missing","If present","Category"],"rows":["Feature A","Feature B"]}],"why":"Separates features people expect from features that delight them, so you do not over-invest in basics.","solo":["List the features. For each one, ask: how would I feel if it were present? If it were missing?","Classify each as must-have, performance, delighter, or indifferent.","Fund the must-haves first, then the delighters."],"team":["Survey 10 to 20 customers with the same two questions.","Compare the answers with what the team assumed."],"ex":"A secure checkout meets a basic expectation. Live tracking can delight users who did not expect it.","src":"Noriaki Kano and colleagues (1984).","sample":["Secure checkout · basic need","Live tracking · delight"],"fr":{"n":"Modèle de Kano","why":"Distingue les attentes de base des fonctions qui surprennent ou améliorent la satisfaction.","solo":["Demande comment la personne réagit si la fonction existe","Pose la même question si elle manque","Classe les deux réponses ensemble"],"team":["Testez les questions auprès de clients","Comptez les catégories par fonction","Traitez les attentes de base"],"d":["grid",{"cols":["Fonction","Si absente","Si présente","Catégorie"],"rows":["Fonction A","Fonction B"]}],"src":"Noriaki Kano et ses collègues (1984).","sample":["Paiement sécurisé · attente de base","Suivi en direct · attrait"],"ex":"Le paiement sécurisé répond à une attente de base. Le suivi en direct peut faire plaisir aux personnes qui ne l’attendaient pas.","sampleCells":{"c0-0":"Paiement sécurisé","c0-1":"Cela me gêne","c0-2":"Je m’y attends","c0-3":"Attente de base","c1-0":"Suivi en direct","c1-1":"Indifférent","c1-2":"Cela me plaît","c1-3":"Attrait"},"exampleNote":"Le paiement sécurisé répond à une attente de base. Le suivi en direct peut faire plaisir aux personnes qui ne l’attendaient pas.","case":{"scene":"Une boutique veut savoir si le suivi de commande compte autant pour les acheteurs que la sécurité du paiement.","check":"Pose les deux questions à des acheteurs et compare la catégorie la plus fréquente pour chaque fonction."}},"sampleCells":{"c0-0":"Secure checkout","c0-1":"I dislike it","c0-2":"I expect it","c0-3":"Basic need","c1-0":"Live tracking","c1-1":"Neutral","c1-2":"I like it","c1-3":"Delight"},"exampleNote":"A secure checkout meets a basic expectation. Live tracking can delight users who did not expect it.","case":{"scene":"An online shop wants to learn whether tracking matters as much to buyers as secure payment.","check":"Test both questions with buyers and compare the most frequent classification for each feature."}},
  {"id":"gtd","n":"Getting Things Done (GTD)","f":"organise","m":"solo","t":30,"rec":true,"fm":"casual","out":["me"],"d":["flow",["Capture everything","Clarify: is it actionable?","Trash, someday or reference","Under two minutes? Do it","Otherwise schedule or delegate","Review weekly"]],"why":"Empties your head into one trusted list, then decides what each item needs next.","solo":["Write everything on your mind into one inbox, on paper or in an app.","Process the inbox. Not actionable goes to trash, someday or reference.","If it takes under two minutes, do it now. Otherwise schedule it or delegate it.","Review all lists every week."],"team":["Each person keeps their own inbox. The team shares only the project lists.","Agree one place for team actions, so nothing waits in a private inbox."],"ex":"Turn the supplier thread into a concrete next action. Keep its invoice as reference and review the follow-up on Friday.","src":"David Allen, Getting Things Done (2001).","sample":["Supplier email","Request a quote","File the invoice","Confirm receipt","Schedule follow-up","Friday at 3 pm"],"fr":{"n":"Méthode GTD","why":"Sors les engagements de ta tête et transforme-les en prochaines actions visibles.","solo":["Collecte les engagements","Définis une prochaine action concrète","Révise les listes chaque semaine"],"team":["Créez une boîte de collecte","Attribuez chaque action","Revoyez les engagements ouverts"],"d":["flow",["Collecter","Clarifier","Écarter ou archiver","Faire en deux minutes","Planifier ou déléguer","Revoir chaque semaine"]],"src":"David Allen, Getting Things Done (2001).","sample":["Courriel fournisseur","Demander un devis","Archiver la facture","Confirmer la réception","Planifier la relance","Vendredi à 15 h"],"ex":"Transforme l’échange fournisseur en prochaine action. Archive la facture et vérifie la relance vendredi.","exampleNote":"Transforme l’échange fournisseur en prochaine action. Archive la facture et vérifie la relance vendredi.","case":{"scene":"Les engagements fournisseurs sont dispersés dans les courriels. Un devis demande une relance et une facture doit simplement être archivée.","check":"Vendredi, vérifie que chaque échange ouvert a une prochaine action datée."}},"exampleNote":"Turn the supplier thread into a concrete next action. Keep its invoice as reference and review the follow-up on Friday.","case":{"scene":"Supplier commitments are scattered across inbox threads. One quote needs a follow-up and one invoice only needs filing.","check":"At Friday’s review, verify that every open supplier thread has a dated next action."}},
  {"id":"two-minute","n":"Two-Minute Rule","f":"organise","m":"solo","t":10,"rec":true,"fm":"casual","out":["me"],"d":["flow",["Task arrives","Under two minutes?","Yes: do it now","No: schedule or delegate"]],"why":"Clears small tasks as they come, so they stop waiting in a list where they grow.","solo":["When a task appears, estimate how long it takes.","Under two minutes: do it at once.","Over two minutes: put it on the list or in the calendar."],"team":["Apply it to team requests. Answer quick questions in the thread instead of booking a call."],"ex":"Confirming the room takes one minute. Put the preparation itself on the calendar.","src":"David Allen, Getting Things Done (2001).","sample":["Room confirmation","One minute","Reply yes","Schedule preparation"],"fr":{"n":"Règle des deux minutes","why":"Traite sur-le-champ une action très courte pendant le tri des tâches.","solo":["Évalue la durée réelle","Fais l’action si elle prend moins de deux minutes","Note une prochaine action dans le cas contraire"],"team":["Définissez ce qui relève du tri","Évitez les interruptions en travail concentré","Orientez les tâches plus longues"],"d":["flow",["Action reçue","Estimation","Faire maintenant","Planifier ou déléguer"]],"src":"David Allen, Getting Things Done (2001).","sample":["Confirmation de salle","Une minute","Répondre oui","Planifier la préparation"],"ex":"Confirmer la salle prend une minute. Réserve du temps dans l’agenda pour la préparation.","exampleNote":"Confirmer la salle prend une minute. Réserve du temps dans l’agenda pour la préparation.","case":{"scene":"Une réservation de salle demande une réponse par oui ou non. La préparation de la réunion prendra une demi-heure.","check":"Confirme pendant le tri et réserve une plage distincte pour préparer la réunion."}},"exampleNote":"Confirming the room takes one minute. Put the preparation itself on the calendar.","case":{"scene":"A room reservation needs a yes-or-no reply. Preparation for the same meeting will take half an hour.","check":"Send the confirmation during triage and reserve a separate block for preparation."}},
  {"id":"time-blocking","n":"Time Blocking","f":"organise","m":"both","t":30,"rec":true,"fm":"casual","out":["me","manager"],"d":["timeline",["Deep work","Meetings","Admin","Calls","Plan tomorrow"]],"why":"Gives each type of work a fixed slot in the calendar, so tasks compete for time, not for your attention.","solo":["Block the week: deep work, admin, meetings, breaks.","Put each task into the block that matches it.","When a block ends, stop, even if the task is not finished."],"team":["Share blocks: meeting-free mornings for focus work across the team.","Agree which blocks are open for interruptions."],"ex":"Protect writing at 9 am. Put calls and invoices in their own slots.","src":"No single inventor. Widely described in productivity writing, for example Cal Newport, Deep Work (2016).","sample":["9 am writing","11 am team","1 pm invoices","3 pm supplier","4:45 pm plan"],"fr":{"n":"Blocs de temps","why":"Réserve des plages à des activités précises dans l’agenda.","solo":["Liste tes activités","Réserve des plages et des marges","Ajuste selon le temps réellement utilisé"],"team":["Identifiez les plages protégées","Regroupez les réunions","Révisez le calendrier en fin de semaine"],"d":["timeline",["Concentration","Réunions","Administration","Appels","Plan du lendemain"]],"src":"Origine diffuse. Cal Newport décrit la pratique dans Deep Work (2016).","sample":["9 h rédaction","11 h équipe","13 h factures","15 h fournisseur","16 h 45 plan"],"ex":"Protège la rédaction à 9 h. Réserve des plages distinctes aux appels et aux factures.","exampleNote":"Protège la rédaction à 9 h. Réserve des plages distinctes aux appels et aux factures.","case":{"scene":"Une personne a raté deux séances de rédaction parce que les appels et les factures ont occupé la matinée.","check":"Vérifie si le créneau de 9 h est utilisé trois jours de suite."}},"exampleNote":"Protect writing at 9 am. Put calls and invoices in their own slots.","case":{"scene":"A writer has missed two drafting sessions because calls and invoices filled the morning.","check":"Track whether the 9 am block actually happens three days in a row."}},
  {"id":"personal-kanban","n":"Personal Kanban","f":"organise","m":"both","t":30,"rec":true,"fm":"structured","out":["me","manager"],"d":["columns",["To do","Doing · WIP 2","Done"]],"why":"Visualise your personal workload and limit work in progress rather than starting everything.","solo":["Put all current tasks on cards.","Choose a maximum of two active tasks.","Move cards to Done before pulling new work."],"team":["Ask each participant to complete the personal kanban canvas individually.","Compare patterns without forcing early agreement.","Finish with one owner, one action and a date."],"ex":"Finish reviewing the contract before pulling more work if the in-progress limit is reached.","src":"Jim Benson and Tonianne DeMaria Barry, Personal Kanban (2011).","sample":["Draft the quote","Review the contract","Send the invoice"],"fr":{"n":"Kanban personnel","why":"Rends tes tâches visibles et limite le nombre de travaux en cours.","solo":["Crée trois colonnes","Déplace au maximum deux tâches en cours","Termine une tâche avant d’en tirer une autre"],"team":["Rendez visibles les blocages","Respectez la limite","Revoyez les cartes anciennes"],"d":["columns",["À faire","En cours · limite de 2","Terminé"]],"src":"Jim Benson et Tonianne DeMaria Barry, Personal Kanban (2011).","sample":["Préparer le devis","Relire le contrat","Envoyer la facture"],"ex":"Si la limite de travaux en cours est atteinte, termine la relecture du contrat avant de prendre une autre tâche.","exampleNote":"Si la limite de travaux en cours est atteinte, termine la relecture du contrat avant de prendre une autre tâche.","case":{"scene":"Un indépendant a un devis, un contrat et une facture en cours. Les changements de tâche retardent les trois.","check":"Garde au plus deux tâches en cours et compare le nombre terminé vendredi."}},"exampleNote":"Finish reviewing the contract before pulling more work if the in-progress limit is reached.","case":{"scene":"A freelancer has a quote, a contract and an invoice open at the same time. Switching is delaying all three.","check":"Keep no more than two active items and compare how many finish by Friday."}},
  {"id":"kanban","n":"Kanban Board","f":"organise","m":"both","t":30,"rec":true,"fm":"casual","out":["me","manager","clients"],"d":["columns",["To do","Doing","Done"]],"why":"Shows all work as cards in columns. A limit on Doing stops you starting ten things at once.","solo":["Draw three columns: To do, Doing, Done.","Write each task on a card in To do.","Move one card to Doing. Keep Doing to two cards at most."],"team":["Add a Blocked column and a limit on Doing per person.","Review the board at the daily standup. Move cards, do not report them."],"ex":"If refunds pile up at finance approval, look at that step before accepting more requests.","src":"David J. Anderson, Kanban (2010). Roots in the Toyota Production System (Taiichi Ohno).","sample":["Refund request","Finance approval","Refund issued"],"fr":{"n":"Kanban d’équipe","why":"Observe la circulation du travail et les étapes où les demandes s’accumulent.","solo":["Cartographie le flux","Fixe une limite par étape","Observe les cartes qui stagnent"],"team":["Visualisez le flux réel","Aidez l’étape saturée","Ajustez les limites après observation"],"d":["columns",["À faire","En cours","Terminé"]],"src":"David J. Anderson, Kanban (2010). Racines dans le système de production Toyota.","sample":["Demande de remboursement","Validation financière","Remboursement effectué"],"ex":"Si les remboursements s’accumulent à la validation financière, examine cette étape avant d’accepter d’autres demandes.","exampleNote":"Si les remboursements s’accumulent à la validation financière, examine cette étape avant d’accepter d’autres demandes.","case":{"scene":"Les demandes de remboursement s’accumulent à la validation financière. En accepter davantage ne fait pas avancer la file.","check":"Compare l’ancienneté des remboursements en attente avant et après le renfort à la validation."}},"exampleNote":"If refunds pile up at finance approval, look at that step before accepting more requests.","case":{"scene":"Refund requests build up at finance approval. Taking more requests does not move the queue.","check":"Review the age of pending refunds before and after helping finance clear the queue."}},
  {"id":"bullet-journal","n":"Bullet Journal","f":"organise","m":"both","t":30,"rec":true,"fm":"structured","out":["me","manager"],"d":["columns",["Rapid log","Daily log","Monthly log","Future log"]],"why":"Use rapid logging and intentional review to keep notes, plans and tasks in one place.","solo":["Capture tasks, events and notes using short symbols.","Review and migrate unfinished items.","Keep a monthly and future log for what matters later."],"team":["Ask each participant to complete the bullet journal canvas individually.","Compare patterns without forcing early agreement.","Finish with one owner, one action and a date."],"ex":"Record the idea quickly. Move dated commitments to the appropriate log at review time.","src":"Ryder Carroll, The Bullet Journal Method (2018).","sample":["Topic idea","Review the draft","Submit on the 25th","Renewal in June"],"fr":{"n":"Journal à puces","why":"Centralise les notes et les tâches dans des journaux que tu révises régulièrement.","solo":["Note en phrases courtes","Marque les tâches et les événements","Reporte seulement ce qui compte encore"],"team":["Convenez de symboles communs","Séparez les notes privées du suivi collectif","Revoyez les échéances ensemble"],"d":["columns",["Notes rapides","Journal du jour","Journal du mois","Journal futur"]],"src":"Ryder Carroll, The Bullet Journal Method (2018).","sample":["Idée de sujet","Relire le brouillon","Rendre le dossier le 25","Renouvellement en juin"],"ex":"Note l’idée rapidement. Lors du bilan, reporte les engagements datés dans le journal qui convient.","exampleNote":"Note l’idée rapidement. Lors du bilan, reporte les engagements datés dans le journal qui convient.","case":{"scene":"Une étudiante note ses idées et ses échéances dans plusieurs carnets et oublie un renouvellement.","check":"Au prochain bilan, retrouve les dates du renouvellement et du devoir en moins d’une minute."}},"exampleNote":"Record the idea quickly. Move dated commitments to the appropriate log at review time.","case":{"scene":"A student records ideas and deadlines in several notebooks and misses a renewal date.","check":"At the next review, find the renewal and assignment deadlines in under one minute."}},
  {"id":"para","n":"PARA Method","f":"organise","m":"both","t":30,"rec":true,"fm":"structured","out":["me","manager"],"d":["columns",["Projects","Areas","Resources","Archives"]],"why":"Organise digital information by actionability rather than by abstract topics.","solo":["Sort files into active Projects, ongoing Areas, reference Resources and Archives.","Move completed projects into Archives.","Review active projects before creating new folders."],"team":["Ask each participant to complete the para canvas individually.","Compare patterns without forcing early agreement.","Finish with one owner, one action and a date."],"ex":"The redesign is a project with an end. Budget management stays active as an ongoing responsibility.","src":"Tiago Forte, Building a Second Brain (2022).","sample":["Website redesign","Budget management","Navigation examples","2025 site"],"fr":{"n":"Classement PARA","why":"Range l’information selon son usage dans un projet ou une responsabilité.","solo":["Identifie tes projets actifs","Trie les notes selon leur usage","Archive ce qui est terminé"],"team":["Définissez les dossiers communs","Nommez un responsable par espace","Archivez à la clôture"],"d":["columns",["Projets","Responsabilités","Ressources","Archives"]],"src":"Tiago Forte, Building a Second Brain (2022).","sample":["Refonte du site","Gestion du budget","Exemples de navigation","Site 2025"],"ex":"La refonte est un projet qui se termine. La gestion du budget reste une responsabilité permanente.","exampleNote":"La refonte est un projet qui se termine. La gestion du budget reste une responsabilité permanente.","case":{"scene":"Une équipe de refonte range ensemble les fichiers actifs, les procédures budgétaires et les anciens visuels du site.","check":"Demande à un collègue de retrouver la maquette actuelle et la version 2025 sans aide."}},"exampleNote":"The redesign is a project with an end. Budget management stays active as an ongoing responsibility.","case":{"scene":"A redesign team stores active files, budget procedures and old website assets together.","check":"Ask a teammate to find the current mock-up and the 2025 version without help."}},
  {"id":"smart","n":"SMART Goals","f":"organise","m":"both","t":30,"rec":true,"fm":"structured","out":["me","manager"],"d":["flow",["Specific","Measurable","Achievable","Relevant","Time-bound"]],"why":"Turn vague ambitions into specific, measurable and time-bounded commitments.","solo":["Write the goal in one sentence.","Add a measure and a realistic target.","Set a date and explain why the goal matters."],"team":["Ask each participant to complete the smart canvas individually.","Compare patterns without forcing early agreement.","Finish with one owner, one action and a date."],"ex":"Define success as a response in 24 hours by 30 June, then check whether two shifts can support it.","src":"George T. Doran, 'There's a S.M.A.R.T. Way to Write Management's Goals and Objectives' (1981).","sample":["Cut response time","48 h to 24 h","With two coverage shifts","Fewer follow-ups","By 30 June"],"fr":{"n":"Objectifs SMART","why":"Transforme une intention en résultat observable assorti d’une échéance.","solo":["Nomme le résultat","Choisis un indicateur et une cible réaliste","Fixe une date de vérification"],"team":["Accordez-vous sur la mesure","Vérifiez les moyens disponibles","Consignez l’échéance"],"d":["flow",["Spécifique","Mesurable","Atteignable","Pertinent","Daté"]],"src":"George T. Doran, article sur les objectifs SMART (1981).","sample":["Réduire le délai de réponse","De 48 h à 24 h","Avec deux permanences","Moins de relances","D’ici au 30 juin"],"ex":"Fixe la cible à 24 h d’ici au 30 juin, puis vérifie si deux permanences suffisent.","exampleNote":"Fixe la cible à 24 h d’ici au 30 juin, puis vérifie si deux permanences suffisent.","case":{"scene":"Les réponses du support prennent en moyenne 48 h. Le responsable dispose de deux permanences pour tester un délai plus court.","check":"Mesure le même délai de réponse le 30 juin et compare-le à la cible de 24 h."}},"exampleNote":"Define success as a response in 24 hours by 30 June, then check whether two shifts can support it.","case":{"scene":"Support replies currently take 48 hours on average. The lead has two coverage shifts to test a shorter target.","check":"Measure the same response-time indicator on 30 June and compare it to the 24-hour target."}},
  {"id":"okr","n":"OKRs","f":"organise","m":"both","t":30,"rec":true,"fm":"structured","out":["me","manager"],"d":["tree",{"root":"Objective","kids":["Key result 1","Key result 2","Key result 3"]}],"why":"Define one qualitative objective and a few measurable results, separate from the tasks used to reach them.","solo":["Write an inspiring but precise objective.","Add two to four measurable key results.","Check progress regularly and adjust initiatives."],"team":["Ask each participant to complete the okr canvas individually.","Compare patterns without forcing early agreement.","Finish with one owner, one action and a date."],"ex":"Track activation, time to first task and drop-off together to see where onboarding improves.","src":"Andy Grove's Intel management practices; John Doerr, Measure What Matters (2018).","sample":["Activation from 45% to 60%","First task in under 3 min","Drop-off below 15%"],"fr":{"n":"Objectifs et résultats clés (OKR)","why":"Relie un objectif qualitatif à quelques résultats chiffrés.","solo":["Écris l’objectif en une phrase","Définis des résultats observables","Mesure les progrès à intervalles réguliers"],"team":["Alignez l’objectif","Désignez les responsables des mesures","Revoyez les écarts chaque semaine"],"d":["tree",{"root":"Objectif","kids":["Résultat clé 1","Résultat clé 2","Résultat clé 3"]}],"src":"Pratiques de gestion d’Andy Grove chez Intel, puis John Doerr, Measure What Matters (2018).","sample":["Activation de 45 à 60 %","Première tâche en moins de 3 min","Abandon sous 15 %"],"ex":"Suis ensemble l’activation, le délai avant la première tâche et l’abandon pour savoir où l’accueil s’améliore.","exampleNote":"Suis ensemble l’activation, le délai avant la première tâche et l’abandon pour savoir où l’accueil s’améliore.","case":{"scene":"Les nouveaux utilisateurs partent souvent avant leur première tâche. L’équipe doit distinguer l’activation, le délai et l’abandon.","check":"Revois les trois mesures chaque semaine avec la même définition de cohorte."}},"exampleNote":"Track activation, time to first task and drop-off together to see where onboarding improves.","case":{"scene":"New users often leave before their first task. The team needs measures that separate activation, speed and drop-off.","check":"Review all three measures weekly on the same cohort definition."}},
  {"id":"raci","n":"RACI Matrix","f":"organise","m":"team","t":30,"rec":false,"fm":"formal","out":["manager","clients"],"d":["grid",{"cols":["Responsible","Accountable","Consulted","Informed"],"rows":["Contract","Budget","Announcement"]}],"why":"Makes explicit who does the work, who signs it off, who is asked, and who is kept informed.","solo":["List the deliverables and the people involved, including you.","For each deliverable, mark one R (does the work) and one A (signs it off).","Mark C (asked) and I (informed) where needed. Check that every row has exactly one A."],"team":["Fill the matrix in the kick-off meeting, with every named person present.","Review it whenever someone joins or leaves the team."],"ex":"Lea drafts the contract. Sam alone approves it, so the contract has a clear owner for sign-off.","src":"No verified single author. A responsibility assignment matrix used in project management for decades.","sample":["Contract · Lea drafts, Sam approves","Budget · Noor prepares, Sam approves","Announcement · Lina drafts, Lea approves"],"fr":{"n":"Matrice des responsabilités RACI","why":"Précise qui exécute, qui valide, qui conseille et qui reçoit l’information.","solo":["Liste les livrables","Attribue les rôles par livrable","Vérifie qu’une personne tranche pour chaque ligne"],"team":["Relisez les rôles ensemble","Résolvez les doubles validations","Partagez la matrice"],"d":["grid",{"cols":["Exécute","Valide","Conseille","Informé"],"rows":["Contrat","Budget","Annonce"]}],"src":"Matrice de répartition des responsabilités utilisée en gestion de projet. Auteur unique non établi.","sample":["Contrat · Léa rédige, Sam valide","Budget · Noor prépare, Sam valide","Annonce · Lina rédige, Léa valide"],"ex":"Léa rédige le contrat. Sam est seul à le valider, ce qui clarifie qui tranche sur ce livrable.","sampleCells":{"c0-0":"Léa","c0-1":"Sam","c0-2":"Noor","c0-3":"Lina","c1-0":"Noor","c1-1":"Sam","c1-2":"Lina","c1-3":"Léa","c2-0":"Lina","c2-1":"Léa","c2-2":"Sam","c2-3":"Noor"},"exampleNote":"Léa rédige le contrat. Sam est seul à le valider, ce qui clarifie qui tranche sur ce livrable.","case":{"scene":"Un contrat reste sans signature parce que plusieurs collègues pensent que quelqu’un d’autre le valide.","check":"Vérifie que chaque livrable a un valideur et que le contrat arrive chez Sam."}},"sampleCells":{"c0-0":"Lea","c0-1":"Sam","c0-2":"Noor","c0-3":"Lina","c1-0":"Noor","c1-1":"Sam","c1-2":"Lina","c1-3":"Lea","c2-0":"Lina","c2-1":"Lea","c2-2":"Sam","c2-3":"Noor"},"exampleNote":"Lea drafts the contract. Sam alone approves it, so the contract has a clear owner for sign-off.","case":{"scene":"A contract sits unsigned because several colleagues think someone else owns the approval.","check":"Confirm that each deliverable has one named approver and that the contract reaches Sam."}},
  {"id":"pomodoro","n":"Pomodoro","f":"focus","m":"both","t":25,"rec":true,"fm":"casual","out":["me"],"d":["cycle",["Work 25 min","Break 5 min","Work 25 min","Break 5 min","Work 25 min","Break 5 min","Work 25 min","Long break"]],"why":"Turns a big block into short sprints with a visible end, which makes starting easier.","solo":["Pick one task. Set a timer for 25 minutes.","Work only on that task until the timer rings.","Take a five-minute break. After four rounds, take a longer one."],"team":["Run the same timer for the whole team on a call. Cameras can stay off.","Agree a shared no-messages window for each round."],"ex":"Use each 25-minute block for a piece of the draft. Take the long pause after the fourth block.","src":"Francesco Cirillo, late 1980s.","sample":["Outline the article","Walk","Write introduction","Drink water","Draft first argument","Stretch","Review the draft","Step outside"],"fr":{"n":"Technique Pomodoro","why":"Alterne des périodes de travail ciblé et de vraies pauses.","solo":["Choisis une tâche","Travaille 25 minutes puis fais une pause de 5 minutes","Prends une pause plus longue après quatre blocs"],"team":["Convenez de plages sans interruption","Notez les demandes à traiter après le bloc","Comparez la durée prévue et réelle"],"d":["cycle",["Travail 25 min","Pause 5 min","Travail 25 min","Pause 5 min","Travail 25 min","Pause 5 min","Travail 25 min","Pause longue"]],"src":"Francesco Cirillo, fin des années 1980.","sample":["Plan du texte","Marcher","Introduction","Boire de l’eau","Premier argument","S’étirer","Relire le brouillon","Sortir"],"ex":"Consacre chaque bloc de 25 minutes à une partie du texte. Prends la pause longue après le quatrième bloc.","exampleNote":"Consacre chaque bloc de 25 minutes à une partie du texte. Prends la pause longue après le quatrième bloc.","case":{"scene":"Un auteur a deux heures pour rédiger et passe aux messages chaque fois que le paragraphe suivant se complique.","check":"Compte les parties rédigées après quatre blocs et note les interruptions."}},"exampleNote":"Use each 25-minute block for a piece of the draft. Take the long pause after the fourth block.","case":{"scene":"An author has two hours for a draft and keeps switching to messages whenever the next paragraph gets difficult.","check":"Count the completed draft sections after four work blocks and record where interruptions occurred."}},
  {"id":"deep-work","n":"Deep Work","f":"focus","m":"solo","t":90,"rec":true,"fm":"casual","out":["me"],"d":["timeline",["Start","Focus block, 60 to 90 min","Break","Focus block, 60 to 90 min","Shallow tasks"]],"why":"Protects long stretches for work that needs full concentration, and moves shallow tasks elsewhere.","solo":["Choose one block of 60 to 90 minutes a day for your hardest work.","Turn off notifications and close unrelated tabs.","Before you stop, write the next step on paper. It makes restarting faster."],"team":["Agree team focus windows, for example mornings with no meetings.","Use a shared status to show when someone is in a focus block."],"ex":"Test and interpret the model in protected blocks. Answer messages after the second block.","src":"Cal Newport, Deep Work (2016).","sample":["Open the data","Test the model","Walk","Interpret results","Reply to messages"],"fr":{"n":"Travail en profondeur","why":"Protège du temps sans interruption pour une tâche exigeante.","solo":["Définis une production attendue","Coupe les interruptions pendant le bloc","Note ce que tu as terminé"],"team":["Protégez une plage commune","Organisez une permanence si nécessaire","Évaluez la production obtenue"],"d":["timeline",["Préparation","Bloc de 60 à 90 min","Pause","Second bloc","Tâches courantes"]],"src":"Cal Newport, Deep Work (2016).","sample":["Ouvrir les données","Tester le modèle","Marcher","Interpréter les résultats","Répondre aux messages"],"ex":"Teste et interprète le modèle pendant les plages protégées. Réponds aux messages après le second bloc.","exampleNote":"Teste et interprète le modèle pendant les plages protégées. Réponds aux messages après le second bloc.","case":{"scene":"Une analyste doit valider un modèle et interpréter ses résultats avant de répondre aux demandes courantes.","check":"Vérifie si les deux blocs ont produit un test reproductible et une interprétation écrite."}},"exampleNote":"Test and interpret the model in protected blocks. Answer messages after the second block.","case":{"scene":"An analyst needs to validate a model and interpret its results before replying to routine requests.","check":"Check whether both focus blocks produced a reproducible test and a written interpretation."}},
  {"id":"shutdown","n":"Shutdown Ritual","f":"focus","m":"both","t":10,"rec":true,"fm":"structured","out":["me","manager"],"d":["flow",["Review inbox","Capture loose ends","Plan tomorrow","Close the day"]],"why":"End each workday with a consistent review and a clear transition out of work.","solo":["Capture unfinished work and stray thoughts.","Identify tomorrow's first priority.","Close work apps and use a consistent sign-off cue."],"team":["Ask each participant to complete the shutdown canvas individually.","Compare patterns without forcing early agreement.","Finish with one owner, one action and a date."],"ex":"Write down the quote follow-up and the 9 am call before closing the laptop.","src":"Cal Newport, Deep Work (2016).","sample":["Two emails","Follow up on the quote","Call at 9 am","Close the laptop"],"fr":{"n":"Rituel de fin de journée","why":"Capture ce qui reste ouvert avant de quitter le travail.","solo":["Parcours les messages","Consigne les prochaines actions","Ferme les outils après avoir préparé demain"],"team":["Établissez une heure de clôture","Consignez les urgences pour la permanence","Respectez la fin de journée"],"d":["flow",["Boîte de réception","Sujets ouverts","Plan de demain","Clôture"]],"src":"Cal Newport, Deep Work (2016).","sample":["Deux courriels","Devis à relancer","Appeler à 9 h","Fermer l’ordinateur"],"ex":"Note la relance du devis et l’appel de 9 h avant de fermer l’ordinateur.","exampleNote":"Note la relance du devis et l’appel de 9 h avant de fermer l’ordinateur.","case":{"scene":"Un devis fournisseur et deux courriels restent en tête après la fermeture de l’ordinateur.","check":"Commence à 9 h par l’appel prévu et vérifie si un engagement ouvert manquait de prochaine action."}},"exampleNote":"Write down the quote follow-up and the 9 am call before closing the laptop.","case":{"scene":"A supplier quote and two emails stay on someone’s mind after the laptop closes.","check":"Start at 9 am with the planned call and check whether any open commitment lacked a next action."}},
  {"id":"maker-manager","n":"Maker’s vs Manager’s Schedule","f":"focus","m":"both","t":30,"rec":true,"fm":"casual","out":["me","manager"],"d":["timeline",["Morning: maker work","Late morning: calls","Afternoon: meetings","End of day: admin"]],"why":"Explains why one meeting in the middle of an afternoon can cost a whole block of focused work.","solo":["Decide whether your work needs long blocks (maker) or short, frequent slots (manager).","Batch the maker work into blocks with no meetings.","Keep meetings short and clustered, in the afternoon."],"team":["Agree meeting-free days or half-days for the team.","Use one shared rule for when a meeting may be booked."],"ex":"Draft the mock-up in the uninterrupted morning. Batch coordination into later slots.","src":"Paul Graham, Maker’s Schedule, Manager’s Schedule (essay, 2009).","sample":["Draft the mock-up","Call the supplier","Decide scope","Approve expenses"],"fr":{"n":"Agendas de création et de coordination","why":"Regroupe les échanges pour préserver de longues plages de production.","solo":["Repère les tâches qui demandent de la continuité","Groupe tes échanges","Teste une semaine et ajuste"],"team":["Fixez des plages de coordination","Protégez les créneaux de production","Revoyez les exceptions"],"d":["timeline",["Création le matin","Appels en fin de matinée","Réunions l’après-midi","Administration en fin de journée"]],"src":"Paul Graham, essai sur les agendas de création et de gestion (2009).","sample":["Écrire la maquette","Appeler le fournisseur","Arbitrer le périmètre","Valider les frais"],"ex":"Prépare la maquette pendant la matinée sans interruption. Regroupe la coordination dans les plages suivantes.","exampleNote":"Prépare la maquette pendant la matinée sans interruption. Regroupe la coordination dans les plages suivantes.","case":{"scene":"Une designer perd toutes ses matinées en réunions, alors qu’une maquette exige deux heures sans interruption.","check":"Au bout d’une semaine, compare le temps de production sans interruption et note les retards de coordination."}},"exampleNote":"Draft the mock-up in the uninterrupted morning. Batch coordination into later slots.","case":{"scene":"A designer loses every morning to meetings, although a mock-up needs two uninterrupted hours.","check":"After a week, compare uninterrupted production time and note any coordination delays."}},
  {"id":"ultradian","n":"90-Minute Focus Cycles","f":"focus","m":"solo","t":90,"rec":true,"fm":"casual","out":["me"],"d":["timeline",["Focus 90","Rest 20","Focus 90","Rest 20"]],"why":"Matches demanding work to a rhythm many people notice in their own attention, with a real break at each end.","solo":["Work in 90-minute blocks on demanding work.","Take a real break after each: stand, walk, do not check messages.","Schedule the hardest work for your usual peak hours."],"team":["Group the team's heavy tasks into the same cycles, so meetings land in the rest periods."],"ex":"Try the same rhythm for data analysis and writing. Observe whether attention drops earlier in either task.","src":"Nathaniel Kleitman, rest-activity cycle research (1950s to 1960s). The 90-minute block is a popular extension, not a settled finding.","sample":["Analyse data","Walk","Draft report","Rest away from screens"],"fr":{"n":"Blocs de concentration et de repos","why":"Teste une alternance de travail et de repos adaptée à ta fatigue.","solo":["Teste une durée de départ","Observe quand ton attention baisse","Raccourcis ou allonge les blocs selon les résultats"],"team":["Laissez chacun ajuster la durée","Respectez les pauses","Comparez les résultats sur une semaine"],"d":["timeline",["Concentration 90 min","Repos 20 min","Concentration 90 min","Repos 20 min"]],"src":"Nathaniel Kleitman, travaux sur le cycle repos–activité (années 1950 à 1960). Les blocs de 90 minutes sont une extrapolation.","sample":["Analyse des données","Promenade","Rédaction","Pause hors écran"],"ex":"Teste le même rythme pour l’analyse et la rédaction. Observe si l’attention baisse plus tôt pour l’une des deux.","exampleNote":"Teste le même rythme pour l’analyse et la rédaction. Observe si l’attention baisse plus tôt pour l’une des deux.","case":{"scene":"Un analyste constate une baisse d’attention en fin de matinée et veut tester un rythme de travail et de repos.","check":"Pendant cinq jours, note quand l’attention baisse et ajuste le bloc suivant d’après ce constat."}},"exampleNote":"Try the same rhythm for data analysis and writing. Observe whether attention drops earlier in either task.","case":{"scene":"An analyst notices attention dropping late in the morning and wants to test a work-rest rhythm.","check":"For five days, record when attention drops and adjust the next block to match the observation."}},
  {"id":"timeboxing","n":"Timeboxing","f":"focus","m":"both","t":45,"rec":true,"fm":"structured","out":["me","manager"],"d":["bars",[["Task A",0,0.5],["Task B",0.5,0.75],["Task C",0.75,1]]],"why":"Fixes the time you spend on something, not the result. When the box ends, you stop and decide.","solo":["Decide how long the task gets before you start.","Set a timer. Work until it rings.","Then choose one: finish, extend once with a stated reason, or stop and log what is left."],"team":["Give each agenda item a fixed time in the meeting invitation.","At the end of each box, decide together what happens next."],"ex":"Stop drafting at 30 minutes. Use the remaining time to review and send a usable version.","src":"James Martin, Rapid Application Development (1991). Used in the DSDM method.","sample":["Outline 30 min","Review 15 min","Send 15 min"],"fr":{"n":"Limites de temps","why":"Fixe une durée maximale et une définition de résultat avant de commencer.","solo":["Définis le résultat minimum","Fixe une limite et lance le minuteur","Arrête-toi pour décider de la suite"],"team":["Accordez-vous sur les limites","Vérifiez le résultat à l’échéance","Reportez le reste explicitement"],"d":["bars",[["Tâche A",0,0.5],["Tâche B",0.5,0.75],["Tâche C",0.75,1]]],"src":"James Martin, Rapid Application Development (1991). Pratique employée dans la méthode DSDM.","sample":["Plan 30 min","Relecture 15 min","Envoi 15 min"],"ex":"Arrête le brouillon au bout de 30 minutes. Garde le reste pour relire et envoyer une version exploitable.","exampleNote":"Arrête le brouillon au bout de 30 minutes. Garde le reste pour relire et envoyer une version exploitable.","case":{"scene":"Une échéance d’une heure laisse juste assez de temps pour un plan, une relecture et un envoi exploitable.","check":"À la trentième minute, arrête la rédaction et vérifie que les points essentiels sont présents."}},"exampleNote":"Stop drafting at 30 minutes. Use the remaining time to review and send a usable version.","case":{"scene":"A one-hour deadline leaves only enough time for an outline, a review and a usable handoff.","check":"At minute 30, stop drafting and verify that the essential points are present."}},
  {"id":"parkinson","n":"Parkinson’s Law","f":"focus","m":"both","t":20,"rec":true,"fm":"structured","out":["me","manager"],"d":["bars",[["Unbounded task",0,1],["Timeboxed task",0,0.45]]],"why":"Set deliberately bounded time for tasks because work can expand to fill the time available.","solo":["Estimate the minimum useful time for the task.","Set a deadline and define what 'good enough' means.","Stop when the timebox ends and review the result."],"team":["Ask each participant to complete the parkinson canvas individually.","Compare patterns without forcing early agreement.","Finish with one owner, one action and a date."],"ex":"Check that the 25-minute version still captures the same decisions as the 60-minute version.","src":"C. Northcote Parkinson, 'Parkinson's Law', The Economist (1955).","sample":["Meeting notes in 60 min","Meeting notes in 25 min, same decisions captured"],"fr":{"n":"Loi de Parkinson","why":"Teste si une échéance plus courte réduit le temps passé sur un travail comparable.","solo":["Observe le temps habituel","Fixe une durée plus courte pour une tâche comparable","Vérifie le résultat et la qualité"],"team":["Choisissez une tâche récurrente","Comparez deux durées","Gardez un contrôle qualité"],"d":["bars",[["Sans limite",0,1],["Avec limite",0,0.45]]],"src":"C. Northcote Parkinson, The Economist (1955).","sample":["Compte rendu en 60 min","Compte rendu en 25 min, mêmes décisions consignées"],"ex":"Vérifie que la version de 25 minutes consigne les mêmes décisions que celle d’une heure.","exampleNote":"Vérifie que la version de 25 minutes consigne les mêmes décisions que celle d’une heure.","case":{"scene":"Le compte rendu hebdomadaire prend une heure. L’essentiel de sa valeur tient aux décisions et à leurs responsables.","check":"Compare les deux versions avec la même liste de décisions à consigner."}},"exampleNote":"Check that the 25-minute version still captures the same decisions as the 60-minute version.","case":{"scene":"Weekly meeting minutes take an hour. Most of the value comes from recording decisions and owners.","check":"Compare both versions against the same decision checklist."}},
  {"id":"implementation","n":"Implementation Intentions","f":"focus","m":"both","t":10,"rec":true,"fm":"structured","out":["me","manager"],"d":["flow",["If situation X","Then I do Y","Try it","Review the cue"]],"why":"Turn an intention into an if–then response triggered by a specific situation.","solo":["Identify the situation where you usually get stuck.","Write an if–then action that is under your control.","Use the cue and improve the plan if needed."],"team":["Ask each participant to complete the implementation canvas individually.","Compare patterns without forcing early agreement.","Finish with one owner, one action and a date."],"ex":"The urgent request is the trigger. Checking its impact is the action to rehearse.","src":"Peter Gollwitzer, implementation-intention research (1990s).","sample":["An urgent request arrives","Check its impact before replying","Try it Monday","Add a triage question"],"fr":{"n":"Plans « si… alors… »","why":"Associe un déclencheur concret à une action définie à l’avance.","solo":["Choisis un signal observable","Écris une réponse faisable","Teste puis change le signal si nécessaire"],"team":["Définissez un scénario fréquent","Répétez la réponse","Revoyez les cas manqués"],"d":["flow",["Si cette situation arrive","Alors je fais ceci","Essai","Ajustement"]],"src":"Peter Gollwitzer, travaux sur les intentions de mise en œuvre (années 1990).","sample":["Si une demande urgente arrive","Je vérifie l’impact avant de répondre","Test lundi","Ajouter une question de tri"],"ex":"La demande urgente est le déclencheur. Vérifier son impact est l’action à répéter.","exampleNote":"La demande urgente est le déclencheur. Vérifier son impact est l’action à répéter.","case":{"scene":"Un message urgent déclenche souvent un oui précipité. L’équipe veut faire un contrôle rapide avant d’accepter un travail.","check":"Compte les contrôles d’impact sur les cinq prochaines demandes urgentes."}},"exampleNote":"The urgent request is the trigger. Checking its impact is the action to rehearse.","case":{"scene":"An urgent message often triggers a rushed yes. The team wants a short check before accepting new work.","check":"Count how often the impact check happens on the next five urgent requests."}},
  {"id":"habit-stack","n":"Habit Stacking","f":"focus","m":"solo","t":10,"rec":true,"fm":"casual","out":["me"],"d":["flow",["Existing habit (after coffee)","New habit (two minutes)","Small reward or next step"]],"why":"Attaches a new habit to one you already have, so you do not need to remember to start it.","solo":["Pick something you do every day without thinking: coffee, brushing your teeth.","Use the form: 'After I [existing habit], I will [new habit].'","Keep the new habit tiny, under two minutes, at first."],"team":["Attach a team habit to an existing meeting. For example, after the standup, each person writes one line of notes."],"ex":"Attach a short planning gesture to coffee, a routine that already happens.","src":"Popularised by BJ Fogg, Tiny Habits (2019), and James Clear, Atomic Habits (2018). No single inventor.","sample":["After coffee","Write today's priority","Put it in the calendar"],"fr":{"n":"Ancrage d’habitude","why":"Accroche une petite habitude à un geste que tu fais déjà.","solo":["Choisis un repère stable","Ajoute un geste de deux minutes","Répète jusqu’à ce qu’il devienne facile"],"team":["Choisissez un rituel commun","Ajoutez un geste bref","Révisez après cinq essais"],"d":["flow",["Habitude existante","Nouvelle habitude","Suite immédiate"]],"src":"Popularisée par BJ Fogg et James Clear. Inventeur unique non établi.","sample":["Après le café","Écrire la priorité du jour","L’inscrire dans l’agenda"],"ex":"Associe un petit geste de planification au café, une habitude déjà installée.","exampleNote":"Associe un petit geste de planification au café, une habitude déjà installée.","case":{"scene":"Une personne oublie de choisir sa priorité avant de travailler, mais prépare son café chaque matin.","check":"Après cinq matins, compte combien de priorités figurent dans l’agenda."}},"exampleNote":"Attach a short planning gesture to coffee, a routine that already happens.","case":{"scene":"A planner forgets to choose a priority before the workday starts but makes coffee every morning.","check":"After five mornings, count how often the priority made it into the calendar."}},
  {"id":"chain","n":"Don’t Break the Chain","f":"focus","m":"solo","t":10,"rec":true,"fm":"casual","out":["me"],"d":["timeline",["Day 1","Day 2","Day 3","Day 4","Day 5","Day 6","Day 7"]],"why":"A visible streak makes a daily habit harder to skip, because the gap shows on the calendar.","solo":["Choose one small daily action.","Mark a cross on a calendar each day you do it.","If you miss a day, restart the next day. Never miss twice in a row."],"team":["Share one calendar in the team channel. Each person marks their own days.","Celebrate streak lengths at the monthly review, not every day."],"ex":"One missed day is visible. Resume the next day and look for what caused the gap.","src":"Attributed to Jerry Seinfeld. The anecdote was reported by Brad Isaacs (2007). The attribution is disputed.","sample":["Done","Done","Missed","Done","Done","Done","Done"],"fr":{"n":"Chaîne d’habitudes","why":"Rends les répétitions visibles avec une marque par jour réalisé.","solo":["Définis une action quotidienne minimale","Coche les jours accomplis","Reprends au prochain jour disponible après un écart"],"team":["Choisissez un geste commun","Suivez les répétitions sans classement individuel","Revoyez les obstacles"],"d":["timeline",["Jour 1","Jour 2","Jour 3","Jour 4","Jour 5","Jour 6","Jour 7"]],"src":"Anecdote rapportée par Brad Isaacs (2007) et attribuée à Jerry Seinfeld. L’attribution est contestée.","sample":["Fait","Fait","Absent","Fait","Fait","Fait","Fait"],"ex":"Le jour manqué reste visible. Reprends le lendemain et cherche ce qui a causé l’écart.","exampleNote":"Le jour manqué reste visible. Reprends le lendemain et cherche ce qui a causé l’écart.","case":{"scene":"Une personne veut s’exercer chaque jour. Un déplacement risque de lui faire manquer une journée.","check":"Vérifie si la pratique reprend après un jour manqué et identifie l’obstacle."}},"exampleNote":"One missed day is visible. Resume the next day and look for what caused the gap.","case":{"scene":"A learner wants to practise every day. Travel makes one day likely to slip.","check":"Check whether practice resumes after a missed day and identify the obstacle."}},
  {"id":"five-whys","n":"Five Whys","f":"decide","m":"both","t":20,"rec":true,"fm":"structured","out":["me","manager"],"d":["flow",["Problem","Why 1","Why 2","Why 3","Why 4","Why 5"]],"why":"Trace a problem past its first explanation by asking 'why?' repeatedly, without assuming five is magic.","solo":["State the problem factually.","Ask why, recording evidence rather than blame.","Stop at a cause you can investigate or change."],"team":["Ask each participant to complete the five whys canvas individually.","Compare patterns without forcing early agreement.","Finish with one owner, one action and a date."],"ex":"Verify why the form is outdated before assigning an owner. Each step is a hypothesis to check.","src":"Toyota production-system practice associated with Sakichi Toyoda.","sample":["Late delivery","Late approval","Incomplete request","Missing field","Old form","No form owner"],"fr":{"n":"Les cinq pourquoi","why":"Remonte des symptômes aux causes vérifiables en posant plusieurs fois la question « pourquoi ? ».","solo":["Décris un incident observable","Cherche une cause puis vérifie-la","Continue jusqu’à une cause sur laquelle agir"],"team":["Partez des faits","Vérifiez les hypothèses avec les personnes concernées","Testez une correction"],"d":["flow",["Problème","Pourquoi 1","Pourquoi 2","Pourquoi 3","Pourquoi 4","Pourquoi 5"]],"src":"Pratique du système de production Toyota associée à Sakichi Toyoda.","sample":["Livraison tardive","Validation tardive","Demande incomplète","Champ absent","Ancien formulaire","Aucun responsable du formulaire"],"ex":"Vérifie pourquoi le formulaire est ancien avant d’en nommer un responsable. Chaque étape est une hypothèse à contrôler.","exampleNote":"Vérifie pourquoi le formulaire est ancien avant d’en nommer un responsable. Chaque étape est une hypothèse à contrôler.","case":{"scene":"Trois livraisons ont pris du retard après l’arrivée de demandes de validation incomplètes.","check":"Vérifie l’absence du champ dans les anciennes demandes. Teste le formulaire corrigé sur les cinq prochaines livraisons."}},"exampleNote":"Verify why the form is outdated before assigning an owner. Each step is a hypothesis to check.","case":{"scene":"Three deliveries were late after approval requests arrived incomplete.","check":"Check past requests for the missing field. Test the revised form on the next five deliveries."}},
  {"id":"six-hats","n":"Six Thinking Hats","f":"decide","m":"team","t":60,"rec":false,"fm":"structured","out":["manager","clients"],"d":["columns",["White: facts","Red: feelings","Black: risks","Yellow: benefits","Green: ideas","Blue: process"]],"why":"Gives a group one way of thinking at a time, so critics and optimists stop talking over each other.","solo":["Write the decision on a page.","Spend five minutes on each hat: facts, feelings, risks, benefits, ideas, process.","Decide after the blue hat, not before."],"team":["A facilitator calls each hat. Everyone speaks only in that mode.","Keep each hat's list on a shared board until the next hat starts."],"ex":"Keep the supplier delay separate from concerns about workload. End by deciding whether to run a pilot.","src":"Edward de Bono, Six Thinking Hats (1985).","sample":["12 requests","Concern about workload","Supplier delay","Less data entry","Limited pilot","Decision Friday"],"fr":{"n":"Les six chapeaux de la réflexion","why":"Sépare faits, émotions, risques, bénéfices, idées et conduite de la discussion.","solo":["Parcours les six angles","Note les contradictions","Choisis une suite concrète"],"team":["Annoncez un angle à la fois","Donnez la parole à chacun","Synthétisez avec le chapeau bleu"],"d":["columns",["Blanc · faits","Rouge · émotions","Noir · risques","Jaune · bénéfices","Vert · idées","Bleu · conduite"]],"src":"Edward de Bono, Six Thinking Hats (1985).","sample":["12 demandes","Crainte de surcharge","Délai fournisseur","Moins de saisie","Pilote limité","Décision vendredi"],"ex":"Sépare le retard fournisseur de l’inquiétude sur la charge. Termine en décidant s’il faut lancer un pilote.","exampleNote":"Sépare le retard fournisseur de l’inquiétude sur la charge. Termine en décidant s’il faut lancer un pilote.","case":{"scene":"Une équipe débat d’un nouveau circuit fournisseur. Les faits, les craintes de surcharge et les idées de pilote se mélangent.","check":"Écris une décision de pilote avec un risque à surveiller et un bénéfice à mesurer."}},"exampleNote":"Keep the supplier delay separate from concerns about workload. End by deciding whether to run a pilot.","case":{"scene":"A team is debating a new supplier workflow. Facts, workload fears and pilot ideas are mixed together.","check":"Write a pilot decision with one risk to monitor and one benefit to measure."}},
  {"id":"premortem","n":"Pre-Mortem","f":"decide","m":"team","t":30,"rec":false,"fm":"structured","out":["manager","clients"],"d":["flow",["Imagine the decision has failed","Each person writes why","Group the causes","Assign a fix to each cause"]],"why":"Asks the team to assume failure in advance, which brings out risks people would hesitate to raise.","solo":["Imagine it is a year from now and the decision failed.","Write three reasons it failed.","For each reason, decide one action that lowers the risk."],"team":["Each person writes their reason on a card, silently.","Read them out, group similar ones, and assign an owner to each group."],"ex":"If approval risk could delay launch, book Tuesday testing now and assign someone to confirm it.","src":"Gary Klein, Harvard Business Review (2007).","sample":["Launch delayed","Testing started too late","Approval risk","Book Tuesday testing"],"fr":{"n":"Pré-mortem","why":"Imagine que le projet a échoué pour faire émerger les causes à prévenir.","solo":["Décris un échec plausible","Liste les causes","Prépare une mesure pour la plus probable"],"team":["Faites écrire chacun en silence","Regroupez les causes","Attribuez les mesures et dates"],"d":["flow",["Échec imaginé","Causes individuelles","Regroupement","Mesures"]],"src":"Gary Klein, Harvard Business Review (2007).","sample":["Lancement reporté","Test trop tardif","Risque de validation","Réserver le test mardi"],"ex":"Si la validation menace le lancement, réserve le test mardi et confie sa confirmation à quelqu’un.","exampleNote":"Si la validation menace le lancement, réserve le test mardi et confie sa confirmation à quelqu’un.","case":{"scene":"Une mise en ligne a une date fixe, mais personne n’a réservé de test ni confirmé la disponibilité des valideurs.","check":"Confirme le créneau de test mardi et la personne qui validera avant le lancement."}},"exampleNote":"If approval risk could delay launch, book Tuesday testing now and assign someone to confirm it.","case":{"scene":"A release has a fixed launch date, but nobody has booked testing or confirmed approval availability.","check":"Confirm the Tuesday test slot and the person who will sign off before the launch date."}},
  {"id":"101010","n":"10/10/10","f":"decide","m":"both","t":15,"rec":true,"fm":"structured","out":["me","manager"],"d":["columns",["In 10 minutes","In 10 months","In 10 years"]],"why":"Test a decision against three time horizons to counter short-term emotional bias.","solo":["Write the decision and two real alternatives.","Imagine the consequences after 10 minutes, 10 months and 10 years.","Choose the option that makes sense across timeframes."],"team":["Ask each participant to complete the 101010 canvas individually.","Compare patterns without forcing early agreement.","Finish with one owner, one action and a date."],"ex":"Saying no feels awkward today, but frees the team for the main project over the next ten months.","src":"Suzy Welch, 10-10-10: A Life-Transforming Idea (2009).","sample":["Awkward to say no","Team free for the main project","Little lasting effect"],"fr":{"n":"Décision 10/10/10","why":"Compare les conséquences d’une décision à trois horizons.","solo":["Écris les options","Imagine leurs conséquences à trois horizons","Choisis en tenant compte des compromis"],"team":["Comparez les horizons","Distinguez faits et hypothèses","Consignez la décision"],"d":["columns",["Dans 10 minutes","Dans 10 mois","Dans 10 ans"]],"src":"Suzy Welch, 10-10-10 (2009).","sample":["Inconfort de dire non","Équipe disponible pour le projet principal","Peu de conséquences"],"ex":"Dire non gêne sur le moment, mais libère l’équipe pour le projet principal pendant les dix prochains mois.","exampleNote":"Dire non gêne sur le moment, mais libère l’équipe pour le projet principal pendant les dix prochains mois.","case":{"scene":"Un projet secondaire séduisant prendrait des ressources à un engagement plus important pendant une grande partie de l’année.","check":"Consigne le compromis et réexamine-le au prochain jalon du projet principal."}},"exampleNote":"Saying no feels awkward today, but frees the team for the main project over the next ten months.","case":{"scene":"An attractive side project would take capacity from a more important commitment for most of the year.","check":"Record the trade-off now and revisit it when the main project reaches its next milestone."}},
  {"id":"regret","n":"Regret Minimization","f":"decide","m":"solo","t":20,"rec":false,"fm":"casual","out":["me"],"d":["timeline",["Now","Age 80: looking back"]],"why":"Places a large decision on a long time line, so the question becomes which regret you would rather avoid.","solo":["Imagine you are 80, looking back on this decision.","Ask which choice you would regret not making.","Write the answer in one sentence, then check it against the facts."],"team":["Each person writes their answer, then the group discusses the reasons, not the answers."],"ex":"If the likely regret is never trying, test a small version of the workshop before committing to more.","src":"Often attributed to Jeff Bezos, who described it in interviews. No written source.","sample":["Unsure about proposing a workshop","Regret never trying it"],"fr":{"n":"Minimisation des regrets","why":"Projette-toi dans le futur pour éclairer un choix difficile à défaire.","solo":["Écris les deux options","Imagine ce que tu regretterais dans chaque cas","Identifie un essai réversible"],"team":["Exposez les regrets possibles","Séparez valeurs et prévisions","Décidez d’un essai limité"],"d":["timeline",["Aujourd’hui","À 80 ans"]],"src":"Méthode souvent attribuée à Jeff Bezos, qui l’a décrite en entretien.","sample":["Hésiter à proposer un atelier","Regret de ne jamais avoir essayé"],"ex":"Si le regret probable est de n’avoir jamais essayé, teste une petite version de l’atelier avant d’aller plus loin.","exampleNote":"Si le regret probable est de n’avoir jamais essayé, teste une petite version de l’atelier avant d’aller plus loin.","case":{"scene":"Une personne aimerait proposer un atelier mais hésite à s’engager dans une série avant de tester la demande.","check":"Teste une petite séance et compare l’expérience au résultat redouté."}},"exampleNote":"If the likely regret is never trying, test a small version of the workshop before committing to more.","case":{"scene":"Someone wants to offer a workshop but fears committing to a series before testing demand.","check":"Run one small session and compare the experience with the feared outcome."}},
  {"id":"second-order","n":"Second-Order Thinking","f":"decide","m":"both","t":30,"rec":false,"fm":"structured","out":["manager","clients"],"d":["tree",{"root":"Decision","kids":["First-order effect","Second-order effect","Third-order effect"]}],"why":"Looks past the immediate result to what that result will cause next.","solo":["Write the decision and its immediate effect (first order).","Ask 'and then what?' for the next two effects.","Decide only after you have looked at the second-order effects."],"team":["Each person traces one chain of effects. Compare where the chains end.","Name who is affected at each step."],"ex":"Faster replies may attract more requests. Watch the size of the queue after changing the response process.","src":"A common idea in decision-making writing; Howard Marks’ investment memos use it. No verified first author.","sample":["Faster response","More requests","Risk of overload"],"fr":{"n":"Effets de second ordre","why":"Examine les réactions et conséquences que le premier effet peut déclencher.","solo":["Écris la décision","Trace une chaîne de conséquences","Vérifie les hypothèses avant d’agir"],"team":["Cartographiez les réactions possibles","Cherchez les effets inattendus","Définissez un signal de suivi"],"d":["tree",{"root":"Décision","kids":["Effet direct","Effet indirect","Effet ultérieur"]}],"src":"Idée courante en prise de décision, décrite notamment par Howard Marks. Premier auteur non établi.","sample":["Réponse plus rapide","Plus de demandes","Risque de saturation"],"ex":"Des réponses plus rapides peuvent attirer plus de demandes. Surveille la file après le changement.","exampleNote":"Des réponses plus rapides peuvent attirer plus de demandes. Surveille la file après le changement.","case":{"scene":"Le support peut répondre plus vite, mais un accès facilité pourrait accroître la demande et recréer un retard.","check":"Suis le délai de réponse et la taille de la file pendant deux semaines."}},"exampleNote":"Faster replies may attract more requests. Watch the size of the queue after changing the response process.","case":{"scene":"Support can speed up replies, but easier access may increase demand and create a new backlog.","check":"Monitor both reply time and queue size for two weeks."}},
  {"id":"weighted","n":"Decision Matrix","f":"decide","m":"both","t":45,"rec":false,"fm":"structured","out":["manager","clients"],"d":["grid",{"cols":["Weight","Option A","Option B","Option C"],"rows":["Cost","Timing","Maintenance"]}],"why":"Compares options against criteria you weight yourself, so the trade-offs are written down, not felt.","solo":["List the criteria that matter: cost, time, fit, and so on.","Give each criterion a weight from 1 to 5.","Score each option from 1 to 5 per criterion, multiply by the weight, and add up the totals."],"team":["Agree the criteria and weights before anyone sees the options.","Score separately, then compare totals and discuss the gaps."],"ex":"Use a 1–5 scale. A and B score 3.70 and C scores 3.90. Test the weights before choosing C.","src":"Pugh matrix, Stuart Pugh (engineering design, 1980s to 1990s). Weighted scoring is its common generalisation.","sample":["Cost · 40%","Timing · 35%","Maintenance · 25%"],"fr":{"n":"Matrice de décision pondérée","why":"Compare plusieurs options selon des critères dont l’importance est explicite.","solo":["Définis les critères et leurs poids","Note chaque option sur la même échelle","Multiplie les notes par les poids et teste la sensibilité"],"team":["Fixez les poids avant de noter","Justifiez les notes","Vérifiez si un poids différent change le choix"],"d":["grid",{"cols":["Poids","Option A","Option B","Option C"],"rows":["Coût","Délais","Maintenance"]}],"src":"La matrice de Stuart Pugh, en conception industrielle, est apparentée à la notation pondérée.","sample":["Coût · 40 %","Délais · 35 %","Maintenance · 25 %"],"ex":"Sur une échelle de 1 à 5, A et B obtiennent 3,70 et C obtient 3,90. Teste les poids avant de retenir C.","sampleCells":{"c0-0":"40 %","c0-1":"5","c0-2":"3","c0-3":"4","c1-0":"35 %","c1-1":"2","c1-2":"5","c1-3":"3","c2-0":"25 %","c2-1":"4","c2-2":"3","c2-3":"5"},"exampleNote":"Sur une échelle de 1 à 5, A et B obtiennent 3,70 et C obtient 3,90. Teste les poids avant de retenir C.","case":{"scene":"Trois fournisseurs se distinguent par le coût, les délais et la maintenance. L’équipe veut fixer les poids avant de voir les totaux.","check":"Modifie le poids des délais et vérifie si le fournisseur C reste premier."}},"sampleCells":{"c0-0":"40%","c0-1":"5","c0-2":"3","c0-3":"4","c1-0":"35%","c1-1":"2","c1-2":"5","c1-3":"3","c2-0":"25%","c2-1":"4","c2-2":"3","c2-3":"5"},"exampleNote":"Use a 1–5 scale. A and B score 3.70 and C scores 3.90. Test the weights before choosing C.","case":{"scene":"Three vendors vary in cost, timing and maintenance. The team wants weights agreed before seeing the totals.","check":"Change the timing weight and check whether vendor C remains first."}},
  {"id":"swot","n":"SWOT Analysis","f":"decide","m":"both","t":30,"rec":true,"fm":"structured","out":["me","manager"],"d":["matrix",{"x":"Internal → external","y":"Helpful → harmful","q":["Strengths","Opportunities","Weaknesses","Threats"]}],"why":"Separate internal strengths and weaknesses from external opportunities and threats.","solo":["Define the decision or strategy you are examining.","List strengths, weaknesses, opportunities and threats.","Translate the strongest insights into actions."],"team":["Ask each participant to complete the swot canvas individually.","Compare patterns without forcing early agreement.","Finish with one owner, one action and a date."],"ex":"Growing demand meets an experienced team, but the budget is limited. Start with a narrowly scoped offer.","src":"Albert Humphrey is often credited; the method's precise origin remains disputed.","sample":["Experienced team","Growing demand","Limited budget","New competitors"],"fr":{"n":"Analyse FFOM (SWOT)","why":"Distingue les facteurs internes et externes qui favorisent ou freinent un projet.","solo":["Définis le projet","Remplis les quatre quadrants avec des faits","Choisis une action qui relie deux éléments"],"team":["Collectez les faits séparément","Classez les facteurs","Transformez les constats en décisions"],"d":["matrix",{"x":"Interne → externe","y":"Favorable → défavorable","q":["Forces","Occasions","Faiblesses","Menaces"]}],"src":"Attribution fréquente à Albert Humphrey. L’origine précise reste discutée.","sample":["Équipe expérimentée","Demande en hausse","Budget limité","Nouveaux concurrents"],"ex":"La demande augmente et l’équipe est expérimentée, mais le budget est limité. Commence par une offre ciblée.","exampleNote":"La demande augmente et l’équipe est expérimentée, mais le budget est limité. Commence par une offre ciblée.","case":{"scene":"Une petite équipe voit la demande augmenter et la concurrence se renforcer, avec un budget de lancement limité.","check":"Teste l’offre ciblée auprès de cinq prospects avant d’élargir son périmètre."}},"exampleNote":"Growing demand meets an experienced team, but the budget is limited. Start with a narrowly scoped offer.","case":{"scene":"A small team sees rising demand and stronger competitors but has a limited launch budget.","check":"Test the narrow offer with five prospects before expanding its scope."}},
  {"id":"cynefin","n":"Cynefin Framework","f":"decide","m":"both","t":30,"rec":true,"fm":"structured","out":["me","manager"],"d":["columns",["Clear","Complicated","Complex","Chaotic"]],"why":"Match your response to the type of situation instead of applying one decision process everywhere.","solo":["Describe the situation without deciding too quickly.","Ask whether cause and effect are obvious, analyzable, emergent or unstable.","Choose best practice, expert analysis, safe-to-fail probes or immediate stabilization accordingly."],"team":["Ask each participant to complete the cynefin canvas individually.","Compare patterns without forcing early agreement.","Finish with one owner, one action and a date."],"ex":"Follow the documented reset procedure. Use a small experiment for a new service and contain a live incident immediately.","src":"Dave Snowden; Snowden and Boone, 'A Leader's Framework for Decision Making', HBR (2007).","sample":["Documented password reset","Expert diagnosis of an outage","Test a new service","Contain a live incident"],"fr":{"n":"Cadre Cynefin","why":"Adapte la manière d’agir à la nature de la situation.","solo":["Décris ce que tu sais","Estime si les causes sont prévisibles","Choisis procédure, expertise, essai ou stabilisation"],"team":["Comparez les diagnostics","Choisissez une réponse","Reclassez si les faits changent"],"d":["columns",["Clair","Compliqué","Complexe","Chaotique"]],"src":"Dave Snowden et Mary Boone, Harvard Business Review (2007).","sample":["Réinitialisation documentée","Expertise sur une panne","Test d’un nouveau service","Isoler un incident actif"],"ex":"Suis la procédure pour une réinitialisation. Teste le nouveau service à petite échelle et isole immédiatement l’incident actif.","exampleNote":"Suis la procédure pour une réinitialisation. Teste le nouveau service à petite échelle et isole immédiatement l’incident actif.","case":{"scene":"Un centre d’assistance gère une réinitialisation documentée, une panne difficile à diagnostiquer, un nouveau service et un incident actif.","check":"Vérifie que la réponse à chaque problème tient compte de son degré d’incertitude."}},"exampleNote":"Follow the documented reset procedure. Use a small experiment for a new service and contain a live incident immediately.","case":{"scene":"A service desk handles a documented reset, a puzzling outage, a new service and an active incident.","check":"Check that each issue receives a response appropriate to its uncertainty."}},
  {"id":"daci","n":"DACI","f":"decide","m":"both","t":20,"rec":true,"fm":"structured","out":["me","manager"],"d":["grid",{"cols":["Driver","Approver","Contributors","Informed"],"rows":["Supplier choice"]}],"why":"Clarify who drives a decision, who approves it and who contributes or is informed.","solo":["Write the decision in one sentence.","Name one Driver and one Approver.","Add Contributors and Informed, then publish the decision date."],"team":["Ask each participant to complete the daci canvas individually.","Compare patterns without forcing early agreement.","Finish with one owner, one action and a date."],"ex":"Sam coordinates the supplier choice and Lea makes the final decision.","src":"DACI decision framework associated with Intuit.","sample":["Choose supplier · Sam drives, Lea decides, Noor contributes, team informed"],"fr":{"n":"Cadre de décision DACI","why":"Clarifie qui pilote la décision, qui tranche, qui contribue et qui doit être informé.","solo":["Définis la question et l’échéance","Nomme le pilote et le décideur","Consulte les contributeurs et diffuse la décision"],"team":["Confirmez les rôles","Rassemblez les avis avant l’échéance","Publiez la décision et sa raison"],"d":["grid",{"cols":["Pilote","Décide","Contribue","Informé"],"rows":["Choix du fournisseur"]}],"src":"Cadre DACI associé à Intuit.","sample":["Choisir le fournisseur · Sam pilote, Léa tranche, Noor contribue, équipe informée"],"ex":"Sam pilote le choix du fournisseur et Léa prend la décision finale.","sampleCells":{"c0-0":"Sam","c0-1":"Léa","c0-2":"Noor","c0-3":"Équipe"},"exampleNote":"Sam pilote le choix du fournisseur et Léa prend la décision finale.","case":{"scene":"Plusieurs personnes contribuent au choix d’un fournisseur sans que personne ne sache qui tranche.","check":"Confirme que Léa tranche à l’échéance et que l’équipe reçoit la justification."}},"sampleCells":{"c0-0":"Sam","c0-1":"Lea","c0-2":"Noor","c0-3":"Team"},"exampleNote":"Sam coordinates the supplier choice and Lea makes the final decision.","case":{"scene":"A supplier decision has several contributors and no clear person responsible for making the final call.","check":"Confirm that Lea decides by the deadline and that the team receives the rationale."}},
  {"id":"weekly-review","n":"Weekly Review","f":"review","m":"solo","t":30,"rec":true,"fm":"casual","out":["me"],"d":["cycle",["Clear inboxes","Review the calendar","Review the lists","Plan the next week"]],"why":"A fixed weekly session that keeps the other systems honest. Without it, lists go stale.","solo":["Pick the same slot each week. Friday afternoon works for many people.","Clear inboxes and capture loose items.","Read last week's list: what got done, what did not, and why.","Choose three priorities for next week and block them in the calendar."],"team":["Run it as a 30-minute team review. Each person shares three priorities.","Write blockers and their owners in the shared tracker."],"ex":"Clear six notes and follow up on two files before reserving Tuesday morning for the next priority.","src":"David Allen, Getting Things Done (2001).","sample":["Process six notes","Confirm appointment","Follow up on two files","Reserve Tuesday morning"],"fr":{"n":"Revue hebdomadaire","why":"Réconcilie notes, agenda et engagements avant de planifier la semaine suivante.","solo":["Traite les entrées","Revois les échéances et les projets","Bloque du temps pour les priorités"],"team":["Partagez les échéances","Revoyez les engagements bloqués","Attribuez les suites"],"d":["cycle",["Vider les boîtes","Revoir l’agenda","Revoir les listes","Planifier la semaine"]],"src":"David Allen, Getting Things Done (2001).","sample":["Traiter six notes","Confirmer le rendez-vous","Relancer deux dossiers","Réserver mardi matin"],"ex":"Traite les six notes et relance les deux dossiers avant de réserver mardi matin à la prochaine priorité.","exampleNote":"Traite les six notes et relance les deux dossiers avant de réserver mardi matin à la prochaine priorité.","case":{"scene":"Six notes et deux dossiers restent ouverts vendredi, et un rendez-vous important attend une confirmation.","check":"Commence lundi sans note inexpliquée et avec un créneau protégé pour la prochaine priorité."}},"exampleNote":"Clear six notes and follow up on two files before reserving Tuesday morning for the next priority.","case":{"scene":"Six notes and two files remain open on Friday, while a key appointment is still unconfirmed.","check":"Start Monday with no unexplained note and a protected block for the next priority."}},
  {"id":"start-stop-continue","n":"Start, Stop, Continue","f":"review","m":"team","t":45,"rec":true,"fm":"casual","out":["manager"],"d":["columns",["Start","Stop","Continue"]],"why":"Turns feedback into three kinds of action: what to begin, what to end, and what to keep.","solo":["Write three lists for the last week: start, stop, continue.","Pick one item from Start and one from Stop.","Test them next week, and note the result."],"team":["Silent writing, then cluster the notes and vote on the top three.","Assign an owner to each action, and review it at the next retrospective."],"ex":"Keep the written follow-up and remove duplicate minutes. Test a short agenda next time.","src":"No verified single author. Common in agile team retrospectives.","sample":["Prepare an agenda","Duplicate meeting notes","Keep written follow-up"],"fr":{"n":"Commencer, arrêter, continuer","why":"Transforme un bilan en trois décisions simples sur les pratiques.","solo":["Note un exemple dans chaque colonne","Choisis le changement le plus utile","Fixe une date de revue"],"team":["Faites écrire chacun","Regroupez et votez","Attribuez une action"],"d":["columns",["Commencer","Arrêter","Continuer"]],"src":"Pratique courante des rétrospectives agiles. Auteur unique non établi.","sample":["Préparer l’ordre du jour","Doubler les comptes rendus","Garder le suivi écrit"],"ex":"Garde le suivi écrit et supprime les comptes rendus en double. Teste un ordre du jour court la prochaine fois.","exampleNote":"Garde le suivi écrit et supprime les comptes rendus en double. Teste un ordre du jour court la prochaine fois.","case":{"scene":"Deux personnes rédigent le même compte rendu. Le suivi écrit est utile, mais la réunion démarre souvent sans ordre du jour.","check":"Vérifie à la prochaine réunion si un ordre du jour et un compte rendu ont suffi."}},"exampleNote":"Keep the written follow-up and remove duplicate minutes. Test a short agenda next time.","case":{"scene":"Two people write the same meeting minutes. The written follow-up is useful, but the meeting often starts without an agenda.","check":"Check at the next meeting whether one agenda and one record were enough."}},
  {"id":"retro","n":"Retrospective","f":"review","m":"both","t":45,"rec":true,"fm":"structured","out":["me","manager"],"d":["columns",["What worked","What didn't","Change next"]],"why":"Reflect on what happened, identify insights and commit to improvements as a team.","solo":["Choose a bounded period or project.","Capture facts and perspectives before debating.","Agree one or two improvements with named owners."],"team":["Ask each participant to complete the retro canvas individually.","Compare patterns without forcing early agreement.","Finish with one owner, one action and a date."],"ex":"Early testing helped. Book the approval slot before the next launch and check whether the delay shrinks.","src":"Norm Kerth, Project Retrospectives: A Handbook for Team Reviews (2001).","sample":["Tests ran early","Approval ran late","Book the slot before launch"],"fr":{"n":"Rétrospective d’équipe","why":"Appuie les améliorations du prochain cycle sur les faits du précédent.","solo":["Reconstitue les faits","Identifie un point de friction","Définis un essai et un indicateur"],"team":["Collectez les faits sans chercher de coupable","Choisissez un essai","Revoyez-le au prochain bilan"],"d":["columns",["Ce qui a marché","Ce qui a coincé","Changement à tester"]],"src":"Norm Kerth, Project Retrospectives (2001).","sample":["Tests passés tôt","Validation en retard","Réserver le créneau avant le lancement"],"ex":"Les tests précoces ont aidé. Réserve la validation avant le prochain lancement et vérifie si le retard diminue.","exampleNote":"Les tests précoces ont aidé. Réserve la validation avant le prochain lancement et vérifie si le retard diminue.","case":{"scene":"La version a passé les tests tôt, mais la validation a pris deux jours de plus.","check":"Compare l’attente après avoir réservé la prochaine validation avant le début de la mise en ligne."}},"exampleNote":"Early testing helped. Book the approval slot before the next launch and check whether the delay shrinks.","case":{"scene":"The release passed tests early but still waited two days for approval.","check":"Compare approval waiting time after booking the next review before the release starts."}},
  {"id":"four-ls","n":"4Ls Retrospective","f":"review","m":"team","t":45,"rec":true,"fm":"casual","out":["manager"],"d":["columns",["Liked","Learned","Lacked","Longed for"]],"why":"Adds 'lacked' and 'longed for' to a retrospective, so people name what was missing, not only what went wrong.","solo":["Write one line per column about your last project or week.","Choose one 'lacked' item and one 'longed for' item to act on.","Put both actions in your calendar for next week."],"team":["Silent writing first, for five minutes. Then group the notes.","Give each action an owner and a due date."],"ex":"The team learned a shortcut but lacked documentation. Record the shortcut before the next test.","src":"No verified single author. Used in agile retrospectives since the 2000s.","sample":["Mutual support","New shortcut","Documentation","Testing time"],"fr":{"n":"Rétrospective des quatre L","why":"Collecte quatre types de retours pour identifier un ajustement concret.","solo":["Écris un fait par rubrique","Cherche les répétitions","Choisis une action testable"],"team":["Rassemblez les notes en silence","Discutez les thèmes récurrents","Attribuez le premier essai"],"d":["columns",["Apprécié","Appris","Manqué","Souhaité"]],"src":"Pratique des rétrospectives agiles depuis les années 2000. Auteur unique non établi.","sample":["Entraide","Nouveau raccourci","Documentation","Temps de test"],"ex":"L’équipe a appris un raccourci mais a manqué de documentation. Consigne-le avant le prochain test.","exampleNote":"L’équipe a appris un raccourci mais a manqué de documentation. Consigne-le avant le prochain test.","case":{"scene":"Une équipe de test apprend un raccourci grâce à l’entraide, mais le groupe suivant manque d’instructions écrites.","check":"Demande à une personne extérieure au groupe initial d’utiliser le raccourci documenté."}},"exampleNote":"The team learned a shortcut but lacked documentation. Record the shortcut before the next test.","case":{"scene":"A test team learns a shortcut through mutual help but lacks written instructions for the next group.","check":"Ask someone outside the original group to use the documented shortcut."}},
  {"id":"after-action","n":"After Action Review","f":"review","m":"team","t":45,"rec":false,"fm":"formal","out":["manager","clients"],"d":["flow",["What was supposed to happen?","What actually happened?","Why was there a difference?","Sustain or improve?"]],"why":"Four questions asked straight after an event, to learn from what went differently from the plan.","solo":["Write what you planned to happen, and what happened.","Explain each difference in one sentence.","Choose one thing to sustain and one thing to improve."],"team":["Hold it within 24 hours, while people still remember the details.","Everyone speaks. The leader speaks last."],"ex":"Delivery slipped by two hours because the data arrived late. Request it the day before the next delivery.","src":"US Army, After Action Review (formalised in the 1970s).","sample":["Delivery at noon","Delivery at 2 pm","Data arrived late","Request data the day before"],"fr":{"n":"Revue après action","why":"Compare ce qui était prévu et ce qui s’est produit pour ajuster la prochaine exécution.","solo":["Retrouve l’objectif initial","Décris le résultat observé","Explique l’écart puis choisis une suite"],"team":["Faites parler les personnes présentes","Vérifiez les faits","Attribuez les changements"],"d":["flow",["Prévu","Observé","Causes de l’écart","À garder ou améliorer"]],"src":"Armée américaine, revue après action formalisée dans les années 1970.","sample":["Livraison à midi","Livraison à 14 h","Données en retard","Demander les données la veille"],"ex":"La livraison a glissé de deux heures parce que les données sont arrivées tard. Demande-les la veille la prochaine fois.","exampleNote":"La livraison a glissé de deux heures parce que les données sont arrivées tard. Demande-les la veille la prochaine fois.","case":{"scene":"Une livraison prévue à midi arrive à 14 h. L’équipe doit comprendre l’écart avant de reprendre le même plan.","check":"Demande les données la veille et relève l’heure réelle de la prochaine livraison."}},"exampleNote":"Delivery slipped by two hours because the data arrived late. Request it the day before the next delivery.","case":{"scene":"A noon delivery arrives at 2 pm. The team needs to understand the gap before repeating the same plan.","check":"Request data the day before and record the actual delivery time on the next run."}},
  {"id":"plus-delta","n":"Plus / Delta","f":"review","m":"team","t":15,"rec":true,"fm":"casual","out":["manager"],"d":["columns",["Plus (keep)","Delta (change)"]],"why":"Two columns and no judgement: what worked, and what should change next time.","solo":["Write what worked and what to change, for the last piece of work.","Make one change before the next piece of work."],"team":["Ask each person for one plus and one delta.","Group the deltas and assign one owner per change."],"ex":"Keep the short demo. Send the materials a day earlier and ask if people arrive better prepared.","src":"No verified single author. Widely used in agile teams.","sample":["Short demo","Send materials the day before"],"fr":{"n":"À garder et à changer (Plus–Delta)","why":"Recueille rapidement ce qui a aidé et ce qui mérite un ajustement.","solo":["Note ce qui t’a aidé","Identifie une friction","Écris un changement concret"],"team":["Demandez un fait par colonne","Choisissez une modification","Testez-la à la prochaine séance"],"d":["columns",["À garder","À changer"]],"src":"Pratique répandue dans les équipes agiles. Auteur unique non établi.","sample":["Démo courte","Envoyer les documents la veille"],"ex":"Garde la démo courte. Envoie les documents un jour plus tôt et vérifie si les personnes arrivent mieux préparées.","exampleNote":"Garde la démo courte. Envoie les documents un jour plus tôt et vérifie si les personnes arrivent mieux préparées.","case":{"scene":"Une démo courte a bien fonctionné, mais les participants ont découvert les documents pendant la séance.","check":"Envoie les documents la veille et vérifie combien de participants arrivent préparés."}},"exampleNote":"Keep the short demo. Send the materials a day earlier and ask if people arrive better prepared.","case":{"scene":"A short demo worked well, but attendees saw the materials for the first time during the session.","check":"Send materials a day early and check how many attendees arrive prepared."}},
  {"id":"pdca","n":"PDCA","f":"review","m":"both","t":30,"rec":true,"fm":"structured","out":["me","manager"],"d":["cycle",["Plan","Do","Check","Act"]],"why":"Improve a process through short cycles of planning, testing, learning and adjustment.","solo":["Plan one small process change.","Try it with a measurable result.","Check the outcome and adopt or adjust the process."],"team":["Ask each participant to complete the pdca canvas individually.","Compare patterns without forcing early agreement.","Finish with one owner, one action and a date."],"ex":"Compare the pilot median of 29 hours with the baseline of 48. Extend the trial before making a permanent change.","src":"Shewhart cycle, popularized by W. Edwards Deming; often called PDCA.","sample":["Baseline 48 h","Pilot on ten requests","Median 29 h","Extend the test"],"fr":{"n":"Cycle PDCA","why":"Teste une amélioration, mesure son effet, puis décide de l’adopter ou de l’ajuster.","solo":["Fixe une mesure avant le test","Essaie à petite échelle","Compare puis décide de la suite"],"team":["Définissez un responsable et une durée","Mesurez le résultat","Documentez la décision"],"d":["cycle",["Planifier","Faire","Vérifier","Agir"]],"src":"Cycle de Shewhart popularisé par W. Edwards Deming.","sample":["Délai initial 48 h","Pilote sur dix demandes","Médiane 29 h","Prolonger l’essai"],"ex":"Compare la médiane du pilote, 29 h, aux 48 h initiales. Prolonge l’essai avant de pérenniser le changement.","exampleNote":"Compare la médiane du pilote, 29 h, aux 48 h initiales. Prolonge l’essai avant de pérenniser le changement.","case":{"scene":"Une équipe support veut réduire un délai médian de 48 h avec une petite modification du traitement des demandes.","check":"Répète le pilote sur un groupe comparable et compare les médianes avant de généraliser."}},"exampleNote":"Compare the pilot median of 29 hours with the baseline of 48. Extend the trial before making a permanent change.","case":{"scene":"A support team wants to reduce a 48-hour median delay with a small change to request handling.","check":"Repeat the pilot on a comparable group and compare medians before standardising."}},
  {"id":"daily-highlight","n":"Daily Highlight","f":"review","m":"both","t":10,"rec":true,"fm":"structured","out":["me","manager"],"d":["flow",["Pick a highlight","Reserve time","Protect the slot","Reflect"]],"why":"Choose one meaningful achievement to protect in today's schedule.","solo":["Ask which single thing would make today satisfying.","Block protected time for it.","At the end of the day, note what helped."],"team":["Ask each participant to complete the daily highlight canvas individually.","Compare patterns without forcing early agreement.","Finish with one owner, one action and a date."],"ex":"Define the highlight as a first page ready for review. Give it the 10 am slot.","src":"Jake Knapp and John Zeratsky, Make Time (2018).","sample":["Finish the first page","10 to 11 am","Mute notifications","Page ready to review"],"fr":{"n":"Priorité du jour","why":"Choisis un résultat qui donnera du sens à ta journée et réserve du temps pour l’obtenir.","solo":["Nomme un seul résultat","Réserve une plage dans l’agenda","Vérifie le soir ce qui a avancé"],"team":["Partagez vos priorités","Protégez les plages utiles","Réajustez en cas de conflit"],"d":["flow",["Choisir","Réserver","Protéger","Faire le bilan"]],"src":"Jake Knapp et John Zeratsky, Make Time (2018).","sample":["Finir la première page","10 h à 11 h","Couper les notifications","Page prête à relire"],"ex":"Définis la priorité comme une première page prête à relire. Réserve-lui le créneau de 10 h.","exampleNote":"Définis la priorité comme une première page prête à relire. Réserve-lui le créneau de 10 h.","case":{"scene":"Une personne a plusieurs tâches courantes, mais veut un résultat concret à la fin de sa journée.","check":"En fin de journée, vérifie si la première page est prête pour une relecture."}},"exampleNote":"Define the highlight as a first page ready for review. Give it the 10 am slot.","case":{"scene":"A writer has several routine tasks but wants one concrete achievement by the end of the day.","check":"At day’s end, check whether the first page is ready for someone else to review."}},
  {"id":"energy-audit","n":"Energy Audit","f":"review","m":"solo","t":30,"rec":true,"fm":"casual","out":["me"],"d":["matrix",{"x":"Energy drained →","y":"Energy gained ↑","q":["Protect it","Limit it","Drop or batch","Cut or fix"]}],"why":"Maps which activities drain your energy and which restore it, not just how long they take.","solo":["For two weeks, note each activity and your energy afterwards: up, flat or down.","Place each activity on the grid by drain and gain.","Protect the work in the top left. Cut or fix the work in the bottom right."],"team":["Each person runs the audit. Compare the Cut or fix lists for shared causes.","Use the results to rebalance meeting load across the team."],"ex":"Protect morning writing. Batch expenses and check whether the change reduces end-of-day fatigue.","src":"Jim Loehr and Tony Schwartz, The Power of Full Engagement (2003).","sample":["Morning writing","Short client call","Batch expenses","Reduce status meetings"],"fr":{"n":"Bilan d’énergie","why":"Observe quelles activités rechargent ou épuisent pour mieux organiser la semaine.","solo":["Note ton énergie avant et après les tâches","Repère les activités qui se répètent","Modifie un créneau et observe l’effet"],"team":["Collectez les tendances librement","Changez un élément de planning","Vérifiez la semaine suivante"],"d":["matrix",{"x":"Énergie dépensée →","y":"Énergie gagnée ↑","q":["Protéger","Limiter","Regrouper ou retirer","Réduire ou corriger"]}],"src":"Jim Loehr et Tony Schwartz, The Power of Full Engagement (2003).","sample":["Rédaction le matin","Réunion client courte","Regrouper les frais","Réduire les réunions de suivi"],"ex":"Protège la rédaction du matin. Regroupe les frais et observe si la fatigue de fin de journée diminue.","exampleNote":"Protège la rédaction du matin. Regroupe les frais et observe si la fatigue de fin de journée diminue.","case":{"scene":"La rédaction est plus facile le matin, alors que les réunions de suivi et les frais épuisent en fin de journée.","check":"Compare l’énergie de l’après-midi pendant une semaine après avoir regroupé les frais et raccourci les réunions."}},"exampleNote":"Protect morning writing. Batch expenses and check whether the change reduces end-of-day fatigue.","case":{"scene":"Writing feels easy in the morning but status meetings and expense admin drain energy later.","check":"Compare afternoon energy for one week after batching expenses and shortening meetings."}},
  {"id":"kaizen","n":"Kaizen","f":"review","m":"both","t":15,"rec":true,"fm":"structured","out":["me","manager"],"d":["cycle",["Notice","Change one thing","Observe","Standardize"]],"why":"Make small, continuous improvements that compound instead of waiting for a dramatic redesign.","solo":["Find a tiny daily friction in your work.","Test one small change.","Keep it if it helps and repeat the cycle."],"team":["Ask each participant to complete the kaizen canvas individually.","Compare patterns without forcing early agreement.","Finish with one owner, one action and a date."],"ex":"Put templates in one folder and time how long they take to find before publishing the convention.","src":"Masaaki Imai, Kaizen: The Key to Japan's Competitive Success (1986).","sample":["Slow template search","Create one folder","Measure search time","Publish the convention"],"fr":{"n":"Amélioration continue (Kaizen)","why":"Essaie de petites améliorations fréquentes et conserve celles dont l’effet est visible.","solo":["Repère une friction récurrente","Teste un petit changement","Mesure puis conserve ou ajuste"],"team":["Invitez les personnes qui font le travail à proposer","Testez un changement à la fois","Documentez le résultat"],"d":["cycle",["Observer","Changer une chose","Mesurer","Formaliser"]],"src":"Masaaki Imai, Kaizen (1986).","sample":["Recherche de modèles lente","Créer un dossier unique","Mesurer le temps de recherche","Publier la convention"],"ex":"Regroupe les modèles dans un dossier et mesure le temps de recherche avant de publier la convention.","exampleNote":"Regroupe les modèles dans un dossier et mesure le temps de recherche avant de publier la convention.","case":{"scene":"Une équipe perd plusieurs minutes chaque jour à chercher le modèle à jour dans différents dossiers.","check":"Chronomètre cinq recherches avant et après la création d’un dossier partagé unique."}},"exampleNote":"Put templates in one folder and time how long they take to find before publishing the convention.","case":{"scene":"A team spends several minutes each day hunting for the current template across folders.","check":"Time five template searches before and after introducing a single shared folder."}}
] };
